COLLDATA("seeratency","ur",[[2400,"سیدنا انس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:\n﴿مَا أَحَدٌ يَدْخُلُ الْجَنَّةَ يُحِبُّ أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَلَهُ مَا عَلَى الْأَرْضِ مِنْ شَيْءٍ إِلَّا الشَّهِيدُ يَتَمَنَّى أَنْ يَرْجِعَ إِلَى الدُّنْيَا فَيُقْتَلَ عَشْرَ مَرَّاتٍ لِّمَا يَرَى مِنَ الْكَرَامَةِ﴾\n’’جو شخص بھی جنت میں داخل ہوگا، وہ کبھی دنیا میں واپس آنے کی خواہش نہیں کرے گا۔ چاہے اسے زمین کی ہر چیز دے دی جائے۔ مگر شہید تمنا کرے گا کہ مجھے دنیا میں واپس بھیجا جائے اور میں دس دفعہ شہید کیا جاؤں کیونکہ اسے شہید کا اعزاز و اکرام نظر آ رہا ہوگا۔‘‘(1)\n§شہید کے اعزازات\nشہید کو اللہ تعالیٰ چھ خاص اعزازات سے نوازتا ہے۔ ان اعزازات کا تذکرہ رسول اللہ صلی اللہ علیہ وسلم کے درج ذیل فرمان میں موجود ہے:\n﴿لِلشَّهِيدِ عِنْدَ اللَّهِ سِتُّ خِصَالٍ: يُغْفَرُ لَهُ فِي أَوَّلِ دُفْعَةٍ وَيُرَى مَقْعَدَهُ مِنَ الْجَنَّةِ، وَيُجَارُ مِنْ عَذَابِ الْقَبْرِ، وَيَأْمَنُ مِنَ الْفَزَعِ الْأَكْبَرِ، وَيُوضَعُ عَلَى رَأْسِهِ تَاجُ الْوَقَارِ، الْيَاقُوتَةُ مِنْهَا خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، وَيُزَوَّجُ اثْنَتَيْنِ وَسَبْعِينَ زَوْجَةً مِّنَ الْحُورِ الْعِينِ، وَيُشَفَّعُ فِي سَبْعِينَ مِنْ أَقَارِبِهِ﴾\n’’شہید کے لیے اللہ تعالیٰ کے ہاں چھ اعزاز ہیں، یعنی خون کی پہلی دھار بہتے ہی اسے معاف کر دیا جاتا ہے اور اس کا جنتی ٹھکانہ اسے دکھایا جاتا ہے۔ اسے عذاب قبر سے بچا لیا جاتا ہے۔ بڑی گھبراہٹ والے دن وہ مطمئن اور مامون رہے گا۔ اس کے سر پر عزت کا تاج رکھا جائے گا جس کا ایک یاقوت دنیا و ما فیہا سے بہتر ہے۔ موٹی، سیاہ و سفید آنکھوں والی بہتر (72) عورتوں سے اسے بیاہ دیا جائے گا۔ اس کے اپنے عزیز و اقارب میں سے ستر افراد کے بارے میں اس کی سفارش قبول کی جائے گی۔‘‘(2)\nقرآن کریم کی چند آیات کریمہ اور احادیث نبویہ سے اللہ کی راہ میں قتال کرنے کی فضیلت بیان کر دی گئی ہے۔ اگرچہ یہ ایک بڑا طویل اور نہایت ایمان افروز موضوع ہے لیکن ہم اسی پر اکتفا کرتے ہوئے اسی عنوان مقدس کے دیگر پہلوؤں کا جائزہ لیتے ہیں۔","",{"v":500330,"fn":"(1) صحیح البخاری: 2817، صحیح مسلم: (109) 1877\n(2) جامع الترمذی: 1663"}],[2401,"§وجوہات فرضیت جہاد\nحق یہ ہے کہ انسان کی اصل وجہ تخلیق اور مقصد حیات صرف اللہ تعالیٰ کی بندگی اور اعلائے کلمۃ الحق ہے۔ دنیا کے ہر انسان تک دین حنیف کا پیغام پہنچانا ہر مسلمان کا فرض ہے۔ اگر کوئی طاغوتی طاقت مسلمانوں کے اس فریضے کی ادائیگی میں مزاحمت کرے تو اسے شائستگی سے سمجھانا، میٹھے اور آسان الفاظ میں روح اسلام سے آگاہ کرنا اور اللہ کی بندگی کی دعوت دینا نہایت ضروری ہے۔ اگر کوئی طاقت یہ ناصحانہ بات بھی نہ مانے اور جزیہ ادا کرنے سے بھی انکاری ہو تو بدرجہ آخر اسلامی مملکت کے سربراہ کے حکم پر اس کے خلاف جہاد کرنا فرض ہو جاتا ہے۔\nاگر کوئی غیر مسلم ملک مسلمانوں کے کسی ملک پر حملہ کر دے تو مسلمانوں کے ملک کو بچانے اور دشمن کی گرفت سے محفوظ رکھنے کے لیے بھی تمام مسلمانوں پر جہاد فرض ہو جاتا ہے۔\nاگر مسلمان بحیثیت اقلیت کسی غیر مسلم ملک میں پُر امن طور پر رہتے ہیں اور غیر مسلموں کی اکثریتی حکومت مسلمانوں کو ان کے دینی معتقدات اور اعمال صالحہ کی زندگی بسر کرنے کی اجازت نہیں دیتی، ان کے معاش و اقتصاد کے وسائل لوٹتی ہے، ان کی توہین کرتی ہے یا ان پر ناحق ظلم ڈھاتی ہے تو ایسے مظلوم مسلمان بھائیوں کی حفاظت و اعانت کے لیے بھی جہاد کرنا ہر مسلمان کا فرض ہے، تاہم رسالت مآب صلی اللہ علیہ وسلم نے دوران جہاد جو امور ملحوظ رکھنے کی تاکید فرمائی ہے، ان کی پابندی شرط لازم ہے۔","",{"v":500331}],[2402,"§جہاد کے اغراض و مقاصد\nجس طرح جہاد ایک عظیم الشان دینی فریضہ ہے، اسی طرح اس کے اہداف اور مقاصد بھی نہایت اعلیٰ اور بے حد اہم ہیں۔ انھیں اللہ رب العزت نے خود متعین فرمایا ہے۔ بعض اہداف و مقاصد اساسی حیثیت رکھتے ہیں جنھیں کسی صورت نظر انداز نہیں کیا جا سکتا۔ اسلامی ریاست کے ضمن میں آپ جنگ و قتال کی وجوہات ملاحظہ کر چکے ہیں۔ یہاں بعض ذیلی مقاصد ہیں جو ضمناً خود بخود شامل ہو جاتے ہیں۔ ان اہداف و مقاصد کا اختصار کے ساتھ ذکر کیا جاتا ہے:\n§صلح اور اسلام کی سر بلندی\nجہاں تک ممکن ہوتا نبی صلی اللہ علیہ وسلم جنگ سے گریز فرماتے تھے اور معاہدہ یا صلح کی تدبیر فرماتے۔ آپ صلی اللہ علیہ وسلم جب کسی اسلامی لشکر کا امیر مقرر فرماتے تھے، اسے ان ہدایات سے نوازتے:\n﴿وَإِذَا لَقِيتَ عَدُوَّكَ مِنَ الْمُشْرِكِينَ فَادْعُهُمْ إِلَى ثَلَاثِ خِصَالٍ - أَوْ خِلَالٍ - فَأَيَّتُهُنَّ مَا أَجَابُوكَ فَاقْبَلْ مِنْهُمْ وَكُفَّ عَنْهُمْ ثُمَّ ادْعُهُمْ إِلَى الْإِسْلَامِ، فَإِنْ أَجَابُوكَ فَاقْبَلْ مِنْهُمْ وَكُفَّ عَنْهُمْ، ثُمَّ ادْعُهُمْ إِلَى التَّحَوُّلِ مِنْ دَارِهِمْ إِلَى دَارِ الْمُهَاجِرِينَ وَأَخْبِرْهُمْ أَنَّهُمْ إِنْ فَعَلُوا ذَلِكَ فَلَهُمْ مَا لِلْمُهَاجِرِينَ وَعَلَيْهِمْ مَا عَلَى الْمُهَاجِرِينَ، فَإِنْ أَبَوْا أَنْ يَتَحَوَّلُوا مِنْهَا فَأَخْبِرْهُمْ أَنَّهُمْ يَكُونُونَ كَأَعْرَابِ الْمُسْلِمِينَ يَجْرِي عَلَيْهِمْ حُكْمُ اللَّهِ الَّذِي يَجْرِي عَلَى الْمُؤْمِنِينَ وَلَا يَكُونُ لَهُمْ فِي الْغَنِيمَةِ وَالْفَيْءِ شَيْءٌ إِلَّا أَنْ يُجَاهِدُوا مَعَ الْمُسْلِمِينَ، فَإِنْ هُمْ أَبَوْا فَسَلْهُمُ الْجِزْيَةَ، فَإِنْ هُمْ أَجَابُوكَ فَاقْبَلْ مِنْهُمْ وَكُفَّ عَنْهُمْ، فَإِنْ هُمْ أَبَوْا فَاسْتَعِنْ بِاللَّهِ وَقَاتِلْهُمْ﴾\n’’اور جب تمھارے مشرک دشمنوں سے آمنا سامنا ہو تو تم ان کو تین باتوں کی دعوت دو۔ ان تینوں میں سے","",{"v":500332}],[2403,"وہ جس بات پر آمادہ ہو جائیں، وہ ان سے قبول کر لو اور ان سے جنگ نہ کرو، چنانچہ انھیں اسلام کی دعوت دو، اگر وہ اس پر آمادہ ہو جائیں تو وہ ان سے قبول کر لو اور ان سے جنگ نہ کرو، پھر انھیں ان کے علاقے سے مہاجرین کے علاقے کی طرف جانے کی دعوت دو اور انھیں بتا دو کہ اگر وہ ایسا کر لیں گے تو ان کے لیے وہی فوائد ہوں گے جو مہاجرین کے لیے ہوں گے اور ان کے وہی فرائض ہوں گے جو مہاجرین کے فرائض ہیں۔ اگر وہ اپنے علاقے کو چھوڑنے سے انکار کر دیں تو انھیں بتا دو کہ ان کا معاملہ بدوی مسلمانوں کی طرح ہوگا۔ ان پر وہی احکام لاگو ہوں گے جو دیگر مومنین پر لاگو ہوتے ہیں اور ان کے لیے مال غنیمت اور مال فے میں کوئی حصہ نہیں ہوگا الا یہ کہ وہ مسلمانوں کے ساتھ مل کر جہاد کریں۔ اگر وہ مسلمان ہونے کا انکار کریں تو ان سے جزیہ طلب کرو۔ اگر وہ آمادہ ہو جائیں تو ان سے جزیہ قبول کر لو اور جنگ نہ کرو، اگر وہ جزیہ دینے سے بھی انکار کر دیں تو اللہ سے مدد طلب کرو اور ان سے جنگ کرو۔‘‘(1)\n§کمزوروں کی مدد\nکمزور، لاچار اور مقہور و مجبور لوگوں کو ظالموں کے ظلم و ستم اور درندگی سے نجات دلانا بھی جہاد کا ایک اہم مقصد ہے۔ مشرکین مکہ اہل اسلام پر ہولناک مظالم کے جو پہاڑ توڑتے رہے اور انھیں مسلسل مشق ستم بناتے رہے اللہ عز و جل نے ان کی بے بسی و بے کسی دیکھ کر انھیں جہاد کی اجازت دے دی۔ ارشاد ربانی ہے:\n﴿وَمَا لَكُمْ لَا تُقَاتِلُونَ فِي سَبِيلِ اللَّهِ وَالْمُسْتَضْعَفِينَ مِنَ الرِّجَالِ وَالنِّسَاءِ وَالْوِلْدَانِ الَّذِينَ يَقُولُونَ رَبَّنَا أَخْرِجْنَا مِنْ هَٰذِهِ الْقَرْيَةِ الظَّالِمِ أَهْلُهَا وَاجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّا وَاجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا ۝﴾\n’’اور (اے مومنو!) تمھیں کیا ہو گیا ہے کہ تم اللہ کی راہ میں اور ان کمزور مردوں اور عورتوں اور بچوں کو چھڑانے کے لیے نہیں لڑتے جو کہتے ہیں: اے ہمارے پروردگار! ہمیں اس بستی سے نکال لے جس کے رہنے والے ظالم ہیں اور ہمارے لیے اپنی طرف سے کوئی حمایتی مقرر فرما دے اور ہمارے لیے اپنے پاس سے کوئی مددگار عطا فرما دے۔‘‘(2)\n§دینی شعائر اور عبادت گاہوں کی حفاظت\nجہاد کے ذریعے سے ہر دور میں دینی شعائر اور عبادت گاہوں کی حفاظت ہوتی رہی ہے۔ آج بھی یہی مقدس","",{"v":500333,"fn":"(1) صحیح مسلم: 1731\n(2) (النساء 4:75)"}],[2404,"عمل مساجد کے تحفظ کا ضامن ہے۔ ارشاد باری تعالیٰ ہے:\n﴿وَلَوْلَا دَفْعُ اللَّهِ النَّاسَ بَعْضَهُم بِبَعْضٍ لَّهُدِّمَتْ صَوَامِعُ وَبِيَعٌ وَصَلَوَاتٌ وَمَسَاجِدُ يُذْكَرُ فِيهَا اسْمُ اللَّهِ كَثِيرًا﴾\n’’اور اگر اللہ لوگوں میں سے بعض کو بعض کے ذریعے سے دفع نہ کرتا تو بلاشبہ خانقاہیں اور گرجے اور یہودی عبادت خانے اور مسجدیں ڈھا دی جاتیں جن میں اللہ کا نام بکثرت ذکر کیا جاتا ہے۔‘‘(1)\n§زمین سے فساد کا خاتمہ\nزمین سے ہر طرح کے فساد اور ظلم کا خاتمہ کر کے امن و امان قائم کرنا بھی جہاد کا ایک اہم ہدف ہے۔ اللہ تعالیٰ نے فرمایا ہے:\n﴿وَلَوْلَا دَفْعُ اللَّهِ النَّاسَ بَعْضَهُم بِبَعْضٍ لَّفَسَدَتِ الْأَرْضُ وَلَٰكِنَّ اللَّهَ ذُو فَضْلٍ عَلَى الْعَالَمِينَ ۝﴾\n’’اور اگر اللہ انسانوں کے ایک (گروہ) کو دوسرے (گروہ) کے ذریعے سے ہٹاتا نہ رہتا تو یقیناً ساری زمین کا نظام بگڑ جاتا لیکن اللہ دنیا والوں پر بڑا فضل فرمانے والا ہے۔‘‘(2)\n§منافقین کو بے نقاب کرنا\nجہاد کے ذریعے سے کھرے اور کھوٹے کی تمیز ہوتی ہے اور دین کا لبادہ اوڑھ کر دین کے خلاف سازشیں کرنے والے منافقین بے نقاب ہوتے ہیں۔ ارشاد ربانی ہے:\n﴿مَا كَانَ اللَّهُ لِيَذَرَ الْمُؤْمِنِينَ عَلَىٰ مَا أَنتُمْ عَلَيْهِ حَتَّىٰ يَمِيزَ الْخَبِيثَ مِنَ الطَّيِّبِ﴾\n’’اللہ مومنوں کو اس حالت میں ہرگز نہ رہنے دے گا جس میں تم اس وقت ہو یہاں تک کہ وہ پاک کو ناپاک سے علیحدہ کر دے۔‘‘(3)\n§کفر و شرک کا خاتمہ\nاللہ کی زمین سے فتنے، یعنی کفر و شرک کا خاتمہ جہاد کا اولین ہدف ہے۔ ارشاد باری تعالیٰ ہے:\n﴿وَقَاتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ لِلَّهِ﴾\n’’اور ان سے لڑتے رہو یہاں تک کہ (کفر و شرک کا) کوئی فتنہ باقی نہ رہے اور دین اللہ کے لیے ہو جائے۔‘‘(4)","",{"v":500334,"fn":"(1) (الحج 22:40)\n(2) (البقرة 2:251)\n(3) (آل عمران 3:179)\n(4) (البقرة 2:193)"}],[2405,"§غلبہ اسلام\nجہاد کا دوسرا بڑا ہدف یہ ہے کہ اللہ کا دین (دستور) اس کائنات میں پھیل جائے اور اس کے بالمقابل سارے من گھڑت نظاموں اور دستوروں کا خاتمہ کر دیا جائے، اس لیے کہ جب زمین اللہ تعالیٰ کی ہے تو اس پر نظام بھی اسی کا چلے گا۔ اللہ تعالیٰ کا فرمان ہے:\n﴿وَقَاتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ كُلُّهُ لِلَّهِ﴾\n’’اور ان سے لڑتے رہو یہاں تک کہ فتنہ باقی نہ رہے اور دین سارے کا سارا اللہ کے لیے ہو جائے۔‘‘(1)\n§کفار کو خوف زدہ اور ان کے منصوبوں کو ناکام بنانا\nجہاد اور اس کی تیاری کے ذریعے سے اسلام دشمنوں کو خوف زدہ کر کے مرعوب رکھا جاتا ہے اور ان کی ناپاک سازشیں خاک میں ملا دی جاتی ہیں تاکہ انھیں مسلمانوں کے خلاف کوئی اقدام کرنے کی جرات نہ ہو سکے۔ ارشاد باری تعالیٰ ہے:\n﴿وَأَعِدُّوا لَهُم مَّا اسْتَطَعْتُم مِّن قُوَّةٍ وَمِن رِّبَاطِ الْخَيْلِ تُرْهِبُونَ بِهِ عَدُوَّ اللَّهِ وَعَدُوَّكُمْ﴾\n’’اور ان (کافروں کے مقابلے کے) لیے تم مقدور بھر قوت اور جنگی گھوڑے تیار رکھو جن سے تم اللہ کے دشمنوں اور اپنے دشمنوں کو ڈرائے رکھو۔‘‘(2)\n§مسلمانوں کی آزمائش، تربیت اور اصلاح\nجہاد میں مسلمانوں کی آزمائش اور تربیت کا پہلو بھی شامل ہے۔ اللہ تعالیٰ چاہتا تو خود ہی کافروں کو نیست و نابود کر دیتا لیکن اس نے مسلمانوں کی آزمائش اور تربیت کے پیش نظر انھیں جہاد کا حکم دیا۔ راہ جہاد میں ایک مسلمان کی جو تربیت ہوتی ہے، وہ کسی اور چیز سے نہیں ہوتی۔ جہاد سے استقامت، جرات و شجاعت اور غیرت کے علاوہ صرف اور صرف اللہ کے لیے اپنی جان تک کا نذرانہ پیش کرنے کا سبق ملتا ہے۔ یہ انسان کو اللہ کی سچی بندگی کرنے والا پسندیدہ مومن بنا دیتا ہے۔ اللہ تعالیٰ کا ارشاد عالی ہے:\n﴿فَإِذَا لَقِيتُمُ الَّذِينَ كَفَرُوا فَضَرْبَ الرِّقَابِ حَتَّىٰ إِذَا أَثْخَنتُمُوهُمْ فَشُدُّوا الْوَثَاقَ فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً حَتَّىٰ تَضَعَ الْحَرْبُ أَوْزَارَهَا ۚ ذَٰلِكَ وَلَوْ يَشَاءُ اللَّهُ لَانتَصَرَ مِنْهُمْ وَلَٰكِن لِّيَبْلُوَ","",{"v":500335,"fn":"(1) (الأنفال 8:39)\n(2) (الأنفال 8:60)"}],[2406,"﴿بَعْضَكُم بِبَعْضٍ ۚ وَالَّذِينَ قُتِلُوا فِي سَبِيلِ اللَّهِ فَلَن يُضِلَّ أَعْمَالَهُمْ ۝ سَيَهْدِيهِمْ وَيُصْلِحُ بَالَهُمْ ۝﴾\n’’چنانچہ جب تم (جہاد میں) ان لوگوں سے ملو جنھوں نے کفر کیا تو (ان کی) گردنیں مارو، حتیٰ کہ جب تم انھیں خوب قتل کر چکو تو (قیدیوں کو) بیڑیوں میں مضبوطی سے باندھ دو، پھر یا تو اس کے بعد ان پر احسان کرنا ہے یا فدیہ (تاوان) لینا ہے، حتیٰ کہ لڑائی اپنے ہتھیار ڈال دے، (حکم) یہی ہے اور اگر اللہ چاہتا تو (خود ہی) ان سے بدلہ لے لیتا، لیکن (اس نے تمھیں حکم دیا ہے) تاکہ وہ تمھیں ایک دوسرے سے آزمائے اور جو لوگ اللہ کی راہ میں قتل (شہید) کیے گئے تو اللہ ان کے اعمال ہرگز ضائع نہیں کرے گا۔ وہ جلد ان کی رہنمائی کرے گا اور ان کے حال کی اصلاح کرے گا۔‘‘(1)\n§اسلامی حکومت و خلافت کا قیام\nجہاد کا ایک عظیم ہدف یہ بھی ہے کہ خلافت اسلامیہ کا قیام عمل میں آئے تاکہ مساوات انسانی اور مواخات اسلامی قائم ہونے کے ساتھ ساتھ تمام فیصلے قرآن و سنت کے مطابق ہوں اور معاشرتی خرابیوں اور بدعتی رسوم و رواج کا قلع قمع کیا جا سکے۔ اسلامی عقائد راسخ ہوں اور فطری ضروریات کے تقاضے بطریق احسن پورے کیے جا سکیں۔ ارشاد باری تعالیٰ ہے:\n﴿إِنَّا أَنزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ لِتَحْكُمَ بَيْنَ النَّاسِ بِمَا أَرَاكَ اللَّهُ﴾\n’’بے شک ہم نے آپ کی طرف یہ کتاب حق کے ساتھ نازل کی ہے تاکہ آپ کو اللہ نے جو سیدھی راہ دکھائی ہے، اس کے مطابق فیصلے کریں۔‘‘(2)","",{"v":500336,"fn":"(1) (محمد 47:4,5)\n(2) (النساء 4:105)"}],[2407,"§معاہدے اور غزوات و سرایا\nنبی صلی اللہ علیہ وسلم کی بعثت مبارکہ کا اصل مقصد اعلائے کلمۃ اللہ اور بطلان باطل تھا۔ جنگ رفع ظلم اور قیام عدل کے لیے ایک ناگزیر اور آخری درجے کی تدبیر تھی۔ اسی مقصد کے پیش نظر مسلمان عین حالت جنگ میں بھی مخالفین کے سامنے شرائط صلح پیش کرتے، اگر وہ مان جاتے تو جنگ نہ کی جاتی۔ اس سے یہ ثابت ہوتا ہے کہ صلح اور قیام امن کا معقول عہد و پیمان ہی مزاج نبوی تھا اور آپ صلی اللہ علیہ وسلم کے نزدیک جہاد کرنا بھی دراصل رفع شر اور قیام امن کے لیے تھا۔\n§غزوات و سرایا\nمشرکین کے خلاف جنگی مہمات دو قسم کی تھیں: 1 غزوات 2 سرایا۔ وہ لشکر جو کفار کے مقابلے کے لیے گئے، ان میں سے بعض میں رسول اللہ صلی اللہ علیہ وسلم نے بہ نفس نفیس خود شرکت فرمائی اور بعض میں آپ صلی اللہ علیہ وسلم نے کسی صحابی کو سالار مقرر کر کے روانہ فرمایا۔ اہل سیر کی اصطلاح میں غزوہ اس فوجی مہم کو کہتے ہیں جس میں نبی صلی اللہ علیہ وسلم بذات خود تشریف لے گئے، چاہے جنگ ہوئی ہو یا نہیں ہوئی۔ اس کے برعکس سریہ اس فوجی مہم کو کہتے ہیں جس میں آپ صلی اللہ علیہ وسلم نے شرکت نہیں فرمائی۔(1) سرایا سریہ کی جمع ہے۔ ان سرایا و غزوات کے بارے میں ضروری تفصیلات درج ذیل ہیں:\n§غزوات کی تعداد\nغزوات و سرایا کی تفصیلات بیان کرنے سے پہلے ضروری ہے کہ غزوات اور سرایا کی تعداد کے بارے میں وضاحت کر دی جائے۔\nغزوات کی تعداد میں مختلف اقوال ہیں: ایک قول یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے 19 غزوات میں شرکت فرمائی۔ ابو اسحاق کی روایت کے مطابق یہ قول زید بن ارقم رضی اللہ عنہ کا ہے۔ ابو اسحاق فرماتے ہیں:\n﴿كُنتُ إِلَىٰ جَنْبِ زَيْدِ بْنِ أَرْقَمَ، فَقِيلَ لَهُ: كَمْ غَزَا النَّبِيُّ صلى الله عليه وسلم مِنْ غَزْوَةٍ؟ قَالَ: تِسْعَ عَشْرَةَ......﴾","",{"v":500337,"fn":"(1) الرحيق المختوم، ص: 197، السيرة النبوية للمهدي: 393,394/1"}],[2408,"’’میں زید بن ارقم کے ایک جانب بیٹھا ہوا تھا کہ ان سے پوچھا گیا: رسول اللہ صلی اللہ علیہ وسلم نے کتنے غزوے کیے ہیں؟ انھوں نے کہا: انیس (19)......‘‘(1)\nموسیٰ بن عقبہ، ابن اسحاق، واقدی، ابن جوزی، دمیاطی اور عراقی کا قول یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے غزوات کی تعداد 27 ہے، اس کے علاوہ بعض علماء نے یہ تعداد 24 اور بعض نے 21 بتائی ہے۔\nغزوات کی تعداد میں یہ فرق حقیقی نہیں بلکہ اس کی وجہ یہ ہے کہ بعض غزوات کے مقامات ایک دوسرے سے بالکل قریب تھے۔ اور بعض غزوات ایک ہی سفر میں پیش آئے، اس لیے بعض حضرات نے قریب الوقوع غزوات کو ایک ہی غزوہ شمار کیا، جبکہ دیگر حضرات نے ان غزوات کو الگ الگ بیان کیا ہے، مثلاً: غزوہ حنین اور طائف ایک ہی سفر میں پیش آئے، چنانچہ بعض حضرات نے انھیں بھی ایک ہی غزوہ لکھا ہے۔ اسی طرح فتح مکہ کو بعض نے غزوات میں شمار کیا اور بعض نے کہا کہ مکہ تو صلح صفائی سے فتح ہوا، لہٰذا اسے غزوہ شمار کرنا صحیح نہیں، اس لیے غزوات کی گنتی میں کمی بیشی تو یقیناً پائی جاتی ہے لیکن اس سے اصل حقائق پر کوئی اثر نہیں پڑتا۔\nان غزوات میں سے 9 غزوات ایسے تھے جن میں کفار کے ساتھ جنگ ہوئی۔ وہ غزوات یہ ہیں: بدر، احد، خندق، قریظہ، مصطلق، خیبر، فتح مکہ، حنین، طائف۔\n§سرایا کی تعداد\nغزوات کی طرح سرایا کی تعداد میں بھی مختلف اقوال ہیں۔ واقدی نے سرایا کی تعداد 47، ابن عبدالبر نے 35 اور ابن اسحاق نے 36 بتائی ہے، ان اقوال کے علاوہ بعض حضرات نے 70 اور 100 کی تعداد بھی بیان کی ہے۔ اس اختلاف کا سبب بھی وہی ہے جو اوپر بیان ہو چکا ہے۔ اب ہم اللہ تعالیٰ کی توفیق سے ان غزوات اور سرایا کے حالات تفصیل سے بیان کرنے کی سعادت حاصل کرتے ہیں۔(2)\n§جہاد فی سبیل اللہ کی شرط\nحدیث میں ہے کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ اس نے پوچھا: اے اللہ کے رسول! لوگ مختلف اغراض و مقاصد کے لیے لڑتے ہیں۔ کوئی مال غنیمت کے حصول کے لیے لڑتا ہے۔ کوئی اپنی شہرت اور ناموری کے لیے لڑتا ہے۔ کوئی اس لیے لڑتا ہے کہ لوگوں میں اس کا مرتبہ ممتاز ہو جائے۔ آخر ان میں سے کون اللہ","",{"v":500338,"fn":"(1) صحیح البخاری: 3949\n(2) المغازي للواقدي: 1/18، شرح الزرقاني على المواهب: 2/220,221"}],[2409,"[تصویر: نقشہ: وہ غزوات جن میں کفار رسول اللہ صلی اللہ علیہ وسلم کے خلاف معرکہ آرا ہوئے]\nاہم مقامات: مدینہ منورہ، مکہ، جدہ، خیبر، حناکیہ، قلعہ زمرد، بنو جہینہ، سوق سویق، قرقرۃ الکدر، دفینہ، جبل رضویٰ، نجد، حجاز، بحیرۂ قلزم (احمر)\nنمبر شدہ غزوات: 1 بدر الکبریٰ، 2 احد، 3 خندق (احزاب)، 4 بنو قریظہ، 5 بنو مصطلق، 6 خیبر، 7 فتح مکہ، 8 حنین، 9 طائف","",{"v":500339,"im":["v5_p339.jpg"]}],[2410,"کی راہ میں لڑتا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللَّهِ هِيَ الْعُلْيَا، فَهُوَ فِي سَبِيلِ اللَّهِ﴾\n’’جو شخص صرف اس لیے لڑے تاکہ اللہ کا کلمہ بلند ہو جائے، بس وہ اللہ کی راہ میں لڑتا ہے۔‘‘(1)\n§قریش مکہ کے جارحانہ ارادے\nقریش مکہ مدینہ میں اسلامی ریاست کے وجود کو اپنی اقتصادی شہ رگ پر چھری تصور کرتے تھے کیونکہ وہ شام جانے والی بین الاقوامی شاہراہ تجارت کے ناکے پر واقع تھی۔ انھیں خوب معلوم تھا کہ اگر اسلامی ریاست کو پنپنے کا موقع مل گیا تو ایک دن یہ ان کی سیادت کو ختم کر دے گی۔ بنا بریں وہ نبی صلی اللہ علیہ وسلم کی جان کے دشمن تھے اور مسلمانوں کے درپے آزار رہتے تھے۔\nقریش مکہ نے انصار کو دھمکی آمیز خط بھی لکھا۔ اس خط کے محرک مکہ کے دو بڑے سردار ابو سفیان اور ابی بن خلف تھے۔ انھوں نے اہل مدینہ کو لکھا:\n’’عربوں میں کوئی قبیلہ ایسا نہیں جس کے ساتھ جنگ لڑنا ہمارے لیے آپ سے جنگ کرنے سے زیادہ ناگوار اور تکلیف دہ ہو۔ لیکن آپ لوگوں نے ہم میں سے ایک شخص کی مدد کرنے کی کوشش کی ہے جو اعلیٰ ترین نسب اور مرتبے کا مالک تھا۔ آپ نے اسے پناہ دی ہے، اسے تحفظ بخشا ہے۔ یقیناً یہ بات شرمناک اور آپ کی طرف سے بڑی غلطی پر مبنی ہے، اس لیے آپ ہمارے اور اس کے درمیان مداخلت نہ کریں۔ اگر اس نے بہتر مقام بنا لیا تو یہ ہمارا حق ہے کہ ہم اس سے فائدہ اٹھائیں۔ اگر اس کے برعکس صورت ہوئی تو ہم دوسروں سے کہیں بڑھ کر اسے سزا دینے کا حق رکھتے ہیں۔‘‘(2)\n§کفار مکہ کا الٹی میٹم\nکعب بن مالک رضی اللہ عنہ نے اس خط کے جواب میں ایک نظم لکھی۔ اسے پڑھ کر بھی اہل مکہ کے حوصلے پست نہ ہوئے۔ انھوں نے مدینہ میں رئیس منافقین عبداللہ بن ابی اور اس کے مشرک دوستوں کو ایک الٹی میٹم بھیجا جس میں انھیں متنبہ کیا گیا:\n’’تم نے ہمارے ایک مفرور ساتھی کو پناہ دی ہے۔ ہم اللہ کی قسم کھا کر کہتے ہیں کہ آپ لوگ اس سے لڑیں","",{"v":500340,"fn":"(1) صحیح مسلم: 1904\n(2) کتاب المحبر، ص: 271"}],[2411,"یا اسے نکال دیں، ورنہ پھر ہم اپنی جمعیت کے ساتھ آپ لوگوں پر حملہ کر دیں گے۔ آپ کے سارے مردوں کو تہ تیغ کر دیں گے اور آپ کی عورتوں کی حرمت پامال کر ڈالیں گے۔‘‘\nاس خط سے مدینہ میں تھوڑی سی تشویش ضرور ہوئی۔ عبداللہ بن ابی اور اس کے بت پرست ساتھی آپ صلی اللہ علیہ وسلم سے لڑائی کے لیے اکٹھے ہو گئے۔ آپ صلی اللہ علیہ وسلم کو پتہ چلا تو آپ نے شرپسندوں کے مجمع میں خود جا کر گفتگو فرمائی۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’قریش نے تم سے ایسی چال کھیلی ہے کہ اگر تم ان کی دھمکیوں میں آ گئے تو تمھارا بہت زیادہ نقصان ہوگا، بہ نسبت اس کے کہ تم ان کی بات سے انکار کر دو، کیونکہ اگر تم مسلمانوں سے لڑو گے تو اپنے ہی ہاتھوں سے اپنے بھائیوں اور فرزندوں کو جو مسلمان ہو چکے ہیں، قتل کرو گے۔‘‘ نبی کریم صلی اللہ علیہ وسلم کی یہ تقریر سن کر سارا مجمع منتشر ہو گیا۔(1) شرپسندوں کو کسی طرف سے بھی کسی کی حمایت حاصل نہ ہوئی۔\n§نبی صلی اللہ علیہ وسلم کے گرد صحابہ کا پہرہ\nبدوی قبائل جو مدینہ کے اطراف و اکناف میں آباد تھے، اپنی بدوی روایات کے پیش نظر اسلامی ریاست کے امکانی دشمن بن سکتے تھے، اس لیے کہ اسلامی ریاست مرکزیت اور اجتماعیت پر قائم تھی اور یہ بات بدوی قبائل کی سرشت کے خلاف تھی۔ مزید برآں ان میں سے بعض لوگوں کے قریش مکہ کے ساتھ حلیفانہ تعلقات بھی تھے۔\nاس لیے نبی صلی اللہ علیہ وسلم یہ خطرہ محسوس کرتے تھے مبادا کوئی مقامی دشمن کفار مکہ سے ساز باز کر کے آپ کو نقصان پہنچا دے۔ سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں کہ مدینہ پہنچنے کے بعد آپ ایک رات جاگتے رہے اور فرمانے لگے:\n﴿لَيْتَ رَجُلًا مِنْ أَصْحَابِي صَالِحًا يَحْرُسُنِي اللَّيْلَةَ﴾\n’’کاش! میرے اصحاب میں سے کوئی صالح شخص رات بھر میری حفاظت کرے۔‘‘\nسیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: ہم اسی حالت میں تھے کہ ہم نے اسلحہ اور جملہ آلات حرب کی جھنکار سنی۔ آپ صلی اللہ علیہ وسلم نے دریافت فرمایا: کون ہے؟ عرض کیا: سعد بن ابی وقاص ہوں۔ فرمایا: کیسے آنا ہوا؟ سعد بن ابی وقاص رضی اللہ عنہ کہنے لگے: مجھے آپ کے بارے میں خوف لاحق ہوا تو آپ کی حفاظت کے لیے حاضر ہو گیا ہوں۔ آپ صلی اللہ علیہ وسلم نے ان کے لیے دعا فرمائی اور پھر سو گئے۔(2)","",{"v":500341,"fn":"(1) سنن ابی داود: 3004\n(2) صحیح البخاری: 2885، صحیح مسلم: 2410"}],[2412,"[تصویر: مکہ مدینہ کا راستہ]\n§مشرکین مکہ کے خلاف رسول اللہ صلی اللہ علیہ وسلم کی حکمت عملی\nاللہ تعالیٰ کی طرف سے جنگ کی اجازت تو دے دی گئی تھی لیکن جن حالات میں دی گئی، وہ محض قریش کے ذہنی فتور و فساد، قوت کے گھمنڈ اور سرکشی کا نتیجہ تھے، اس لیے حکمت کا تقاضا یہ تھا کہ مسلمان اپنے قبضے کی حدیں قریش کی اس تجارتی شاہراہ تک پھیلا دیں جو مکے سے شام تک پھیلتی چلی گئی ہے۔ اس سلسلے میں رسول اللہ صلی اللہ علیہ وسلم نے دو تدابیر اختیار فرمائیں:\nاولاً یہ کہ جو قبائل اس شاہراہ کے ارد گرد یا اس شاہراہ سے مدینے تک کے درمیانی علاقے میں آباد تھے، ان سے مسلمانوں کے حلیف بننے اور جنگ نہ کرنے کا معاہدہ کیا جائے، یہ قریش کو تنہا کرنے کی تدبیر تھی۔\nدوسری تدبیر یہ اختیار فرمائی کہ اس شاہراہ پر چھاپہ مار دستے بھیجے اور انھیں ہدف دیا کہ وہ قریش کے تجارتی قافلوں پر حملے کریں۔ اس کا مقصد یہ تھا کہ مہاجرین مکہ اپنی جو دولت اور مال و اسباب مکہ مکرمہ میں چھوڑ آئے تھے، کفار اکثر و بیشتر وہی مال لوٹ کر اپنے تجارتی دھندے میں لگا رہے تھے، اس لیے ان کفار سے اپنے مال کی بازیابی ناگزیر ہو گئی تھی۔ یہ اسی طرح ممکن تھا کہ مشرکین مکہ جو تجارتی قافلے لے کر ادھر سے گزریں، انھیں گھیر کر اپنے اموال کی بازیابی کی راہ کھولی جائے تاکہ وہ تجارتی مال و اسباب سے محروم ہو کر مسلمانوں پر حملہ کرنے کا منصوبہ نہ بنا پائیں۔","",{"v":500342,"im":["v5_p342.jpg"]}],[2413,"§مدینہ کے نواح میں معاہدے\nجہاد کا مطلب و مقصود اللہ رب العزت کا کلمہ بلند کرنے کے لیے قرآن و سنت کی تعلیمات پر مبنی صالح معاشرے کا قیام ہے۔ فی الحقیقت یہی ہر مسلمان کا مقصد حیات ہے۔ اس مقصد کے حصول کے لیے لسانی، مالی اور جسمانی طور پر مسلسل جد و جہد کرنا اور اسے درجہ کمال تک پہنچا دینا ہی جہاد کہلاتا ہے۔ اس حقیقت کا بلیغ ترین مظہر خود رسالت مآب صلی اللہ علیہ وسلم کی مساعی جمیلہ ہیں۔ آپ مجسمہ رحمت تھے لیکن اللہ کے دین کے غلبے کے لیے جب بھی قتال کی ضرورت ناگزیر ہو گئی، آپ صلی اللہ علیہ وسلم اس ضرورت کے تقاضے یہ تمام و کمال پورے فرمائے اور جہاں آپ کو حلم و تدبر کے ذریعے مقاصد حسنہ کے حصول کی راہ باز ہوتی نظر آئی تو اس موقع پر آپ صلی اللہ علیہ وسلم نے حالات کی مناسبت سے حریفوں سے معاہدے بھی کیے اور ان معاہدوں کی پابندی کا امکان بھر اہتمام فرمایا۔ ایسے ہی پس منظر میں رسول اللہ صلی اللہ علیہ وسلم نے قبیلہ جہینہ کی مختلف شاخوں سے معاہدے کیے۔\n§بنی زرعہ اور بنی ربعہ سے معاہدات نبوی\nجہینہ میں سے بنی زرعہ اور بنی الربعہ سے ایک معاہدہ ہوا اس معاہدے کی عبارت یہ ہے:\n﴿وَكَتَبَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم لِبَنِي زُرْعَةَ وَبَنِي الرَّبْعَةِ مِنْ جُهَيْنَةَ أَنَّهُمْ آمِنُونَ عَلَىٰ أَنْفُسِهِمْ وَأَمْوَالِهِمْ، وَأَنَّ لَهُمُ النَّصْرَ عَلَىٰ مَنْ ظَلَمَهُمْ أَوْ حَارَبَهُمْ إِلَّا فِي الدِّينِ وَالْأَهْلِ، وَلِأَهْلِ بَادِيَتِهِمْ مَنْ بَرَّ مِنْهُمْ وَاتَّقَىٰ مَا لِحَاضِرَتِهِمْ وَاللَّهُ الْمُسْتَعَانُ﴾\n’’رسول اللہ صلی اللہ علیہ وسلم نے جہینہ کی شاخوں بنو زرعہ اور بنو ربعہ کے لیے (معاہدہ) لکھا کہ بلاشبہ ان لوگوں کو ان کے جان و مال کی امان ہے۔ جو شخص ان پر ظلم کرے گا یا ان سے جنگ کرے گا، اس کے خلاف ان کی مدد کی جائے گی سوائے اس کے کہ وہ جنگ دین یا اہل و عیال کے بارے میں ہو۔ ان کے خانہ بدوشوں میں جو نیک اور پرہیزگار ہوگا، اسے وہی حقوق حاصل ہوں گے جو ان کے شہریوں کے ہیں۔ اور اللہ ہی سے مدد طلب کی جاتی ہے۔‘‘","",{"v":500343}],[2414,"§عوسجہ بن حرملہ جہنی سے معاہدہ\nاسی طرح رسول اللہ صلی اللہ علیہ وسلم نے عوسجہ بن حرملہ جہنی کے لیے درج ذیل معاہدہ تحریر کرایا:\nبِسْمِ اللَّهِ الرَّحْمٰنِ الرَّحِيمِ\nهٰذَا مَا أَعْطَى الرَّسُولُ عَوْسَجَةَ بْنَ حَرْمَلَةَ الْجُهَنِيَّ مِنْ ذِي الْمَرْوَةِ أَعْطَاهُ مَا بَيْنَ بَلْكْثَةَ إِلَى الظَّبْيَةِ إِلَى الْجَعَلَاتِ إِلَى جَبَلِ الْقَبِيلَةِ لَا يُحَاقُهُ أَحَدٌ، وَمَنْ حَاقَّهُ فَلَا حَقَّ لَهُ وَحَقُّهُ حَقٌّ۔ كَتَبَهُ الْعَلَاءُ بْنُ عُقْبَةَ\nیہ ذی المروہ (کے علاقے) سے وہ حصہ ہے جو رسول اللہ صلی اللہ علیہ وسلم نے عوسجہ بن حرملہ جہنی کو عطا فرمایا۔ آپ نے انھیں بلکثہ سے الظبیہ تک اور وہاں سے جعلات تک اور جعلات سے جبل قبیلہ تک کا علاقہ دے دیا ہے۔ ان مقامات میں اس سے کوئی مزاحمت نہ کرے، جو مزاحمت کرے گا، وہ ناحق ٹھہرے گا۔ حق عوسجہ ہی کا ہوگا۔ علاء بن عقبہ نے اسے تحریر کیا۔\n§بنو شیخ سے معاہدہ\nرسول اللہ صلی اللہ علیہ وسلم نے بنو شیخ سے جو جہینہ ہی سے تعلق رکھتے تھے، معاہدہ کیا، اس معاہدے کی تحریر یہ ہے:\nبِسْمِ اللَّهِ الرَّحْمٰنِ الرَّحِيمِ\nهٰذَا مَا أَعْطَى مُحَمَّدٌ النَّبِيُّ بَنِي شَيْخٍ مِنْ جُهَيْنَةَ، أَعْطَاهُمْ مَا خَطُّوا مِنْ صُفَيْنَةَ وَمَا حَرَثُوا، وَمَنْ حَاقَّهُمْ فَلَا حَقَّ لَهُ وَحَقُّهُمْ حَقٌّ۔\n[تصویر: ذی المروہ]\n[تصویر: الظبیہ]","",{"v":500344,"im":["v5_p344.jpg"]}],[2415,"§كَتَبَ الْعَلَاءُ بْنُ عُقْبَةَ وَشَهِدَ\n’’یہ دستاویز ہے جو محمد صلی اللہ علیہ وسلم نے قبیلہ جہینہ کے بنی شیخ کو دی۔ آپ نے انھیں صفینہ کا وہ خطہ عطا فرمایا جسے انھوں نے نشان زد کیا اور اس میں کھیتی باڑی کی۔ جو ان سے مزاحمت کرے گا، وہ ناحق ٹھہرے گا اور انھی کا دعویٰ حق ہوگا۔‘‘ اسے علاء بن عقبہ نے تحریر کیا اور گواہ ہوئے۔\n§بنو جرمز سے معاہدہ\nرسول اللہ صلی اللہ علیہ وسلم نے جہینہ میں سے بنو جرمز بن ربیعہ سے بھی تحریری معاہدہ کیا۔\nوَكَتَبَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم لِبَنِي الْجُرْمُزِ بْنِ رَبِيعَةَ وَهُمْ مِنْ جُهَيْنَةَ، أَنَّهُمْ آمِنُونَ بِبِلَادِهِمْ، وَلَهُمْ مَا أَسْلَمُوا عَلَيْهِ، وَكَتَبَ الْمُغِيرَةُ\n[تصویر: وادی صفینہ کا علاقہ]\n’’ان لوگوں کو ان کی بستیوں میں امن دیا گیا ہے، بحالت قبول اسلام ان لوگوں کے پاس جو مال و دولت ہے، وہ سب انھی کا ہے۔(1) یہ معاہدہ مغیرہ نے تحریر کیا۔‘‘\nان تدبیروں کے رُو بہ عمل آنے سے مسلمانوں کی عسکری مہمات کا سلسلہ شروع ہوگیا اور مضافات میں مسلمانوں کے فوجی دستے گشت کرنے لگے۔ مقصود یہی تھا کہ دشمن سے خبردار رہا جائے، مدینے کے گرد و پیش کے راستوں پر عموماً اور مکے کے راستے پر خصوصاً نظر رکھی جائے۔","",{"v":500345,"fn":"(1) الطبقات لابن سعد: 270,271/1","im":["v5_p345.jpg"]}],[2416,"§عسکری مہارتوں تک دسترس\nاس سلسلے میں آپ سرایا کی تفصیلات اگلے صفحات میں ملاحظہ فرمائیں گے۔\nان جنگی کارروائیوں کا سب سے بڑا فائدہ یہ ہوا کہ دشمنوں کو کان ہوگئے کہ مسلمان انھیں روکنے کی پوری صلاحیت رکھتے ہیں، نیز اسلامی فوجوں کی خوب تربیت ہوئی، جنگی مشقوں کے مواقع میسر آئے اور صحرائی راستوں اور دشمنوں کے حالات سے واقفیت کے نت نئے طور طریقے معلوم ہوئے۔ یوں ان کے عسکری تجربے اور حرب و ضرب کی صلاحیتوں میں بیش بہا اضافہ ہوگیا۔","",{"v":500346}],[2417,"سریہ حمزہ رضی اللہ عنہ (سریہ سیف البحر)\nہجرت کے سات ماہ بعد رمضان المبارک میں رسول اللہ صلی اللہ علیہ وسلم نے سب سے پہلا سریہ ارسال کیا۔ اس کا مقصد قریش کے تجارتی قافلے پر چھاپہ مارنا تھا جو شام سے واپس آرہا تھا اور اس کی قیادت ابوجہل کر رہا تھا۔ اس قافلے کی حفاظت کے لیے 300 مسلح محافظ بھی لشکر کے ہمراہ تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے تیس افراد پر مشتمل مجاہدین اسلام کا دستہ تیار کیا۔ یہ سب کے سب مہاجرین تھے۔ انصار کو اس لیے شامل نہیں کیا کہ ان کے ساتھ یہ معاہدہ ہوا تھا کہ اگر کوئی بیرونی طاقت مدینہ منورہ پر حملہ آور ہوگی تو انصار رسول اللہ صلی اللہ علیہ وسلم کا دفاع کریں گے۔ مدینہ سے باہر نکل کر لڑنے کے بارے میں ان سے کوئی معاہدہ نہیں تھا۔ آپ صلی اللہ علیہ وسلم نے ان تیس افراد پر اپنے چچا سیدنا حمزہ رضی اللہ عنہ کو امیر مقرر فرمایا اور اپنے دست مبارک سے ان کا پرچم باندھا۔ یہ پرچم سفید کپڑے کا تھا۔ اس کا علمبردار کناز بن حصین غنوی رضی اللہ عنہ کو بنایا۔\n[تصویر: العیص کا منظر]","",{"v":500347,"im":["v5_p347.jpg"]}],[2418,"جب مسلمانوں کا لشکر عیص کے اطراف میں سیف البحر (ساحل سمندر) کے پاس پہنچا تو قریش کے قافلے سے آمنا سامنا ہوگیا۔ اسی سیف البحر کی مناسبت سے اس سریے کو سریہ سیف البحر بھی کہا گیا ہے۔ اب دونوں نے جنگ کے لیے اپنی صفیں درست کر لیں۔ جنگ شروع ہونے والی تھی کہ قبیلہ جہینہ کے سردار مجدی بن عمرو جہنی جس کے دونوں فریقوں کے ساتھ دوستانہ تعلقات تھے، اس نے جنگ روکنے کے لیے اپنا اثر و رسوخ استعمال کرنا شروع کر دیا۔ کئی مرتبہ وہ فریقین کے کیمپوں میں آیا اور گیا اور انھیں جنگ سے روکنے کی کوشش کرتا رہا۔ آخر دونوں لشکروں نے جنگ نہ کرنے کے لیے اس کی تجویز منظور کر لی، چنانچہ ابوجہل اپنے آدمیوں اور قافلے سمیت مکہ روانہ ہوگیا اور مہاجرین سیدنا حمزہ رضی اللہ عنہ کی قیادت میں بخیر و عافیت مدینہ طیبہ واپس آگئے۔(1)","",{"v":500348,"fn":"(1) شرح الزرقانی علی المواهب: 224,225/2 ، المغازي للواقدي: 20,21/1"}],[2419,"§سریہ عبیدہ بن حارث رضی اللہ عنہ\nہجرت کے آٹھ ماہ بعد شوال کے مہینے میں رسول اللہ صلی اللہ علیہ وسلم نے ایک اور مہم روانہ فرمائی جو ساٹھ مہاجرین پر مشتمل تھی۔ ان کا امیر عبیدہ بن حارث بن مطلب رضی اللہ عنہ کو مقرر فرمایا۔ یہ لشکر مقام رابغ کی طرف روانہ ہوا جو قدید جاتے ہوئے جحفہ سے دس میل کے فاصلے پر واقع ہے۔ اس لشکر کا جھنڈا بھی سفید تھا جسے رسول اللہ صلی اللہ علیہ وسلم نے خود اپنے دست مبارک سے باندھا تھا اور مسطح بن اثاثہ رضی اللہ عنہ کو اسے اٹھانے کا شرف بخشا۔ یہ لشکر بھیجنے کا مقصد بھی قریش کے تجارتی قافلے پر چھاپہ مارنا تھا۔ یہ قافلہ ابوسفیان بن حرب کی قیادت میں دو سو افراد پر مشتمل تھا۔ دونوں لشکروں کی ٹڈ بھیڑ رابغ کی وادی میں ایک چشمے پر ہوئی جسے احیاء کہا جاتا ہے۔ اس موقع پر لڑائی کے لیے صف بستہ ہونے اور تلواروں کو بے نیام کرنے کی نوبت نہیں آئی۔ دونوں گروہوں نے ایک دوسرے پر تیر برسانے ہی پر اکتفا کیا۔ اس موقع پر مسلمانوں میں سب سے پہلے کافروں پر تیرے چلانے والے سیدنا سعد بن ابی وقاص رضی اللہ عنہ تھے اور یہ\n[تصویر: وادی رابغ]","",{"v":500349,"im":["v5_p349.jpg"]}],[2420,"اسلامی جنگوں میں مجاہدین کی طرف سے پہلا تیر تھا۔ سعد بن ابی وقاص رضی اللہ عنہ کے ترکش میں 20 تیر تھے۔ آپ نے اپنے سارے تیر چلائے جو دشمن کے کسی نہ کسی انسان یا حیوان کو زخمی کرتے چلے گئے۔ اس دوران میں ابوسفیان کے لشکر سے دو شخص فرار ہو کر مسلمانوں کے ساتھ آملے۔ یہ دونوں مسلمان تھے اور کفار کے ساتھ اسی مقصد سے نکلے تھے کہ مسلمانوں سے جاملیں گے۔ ایک مقداد بن عمرو بہرانی رضی اللہ عنہ تھے اور دوسرے عتبہ بن غزوان مازنی رضی اللہ عنہ تھے۔ جھڑپ کے بعد دونوں فریق اپنی منزل کی طرف روانہ ہوگئے۔ سعد بن ابی وقاص رضی اللہ عنہ کہتے ہیں کہ میں نے عبیدہ رضی اللہ عنہ سے کہا: کیوں نہ ہم دوبارہ ان پر حملہ کریں اور غنیمت حاصل کریں کیونکہ وہ لوگ جاتے ہوئے بہت خوفزدہ تھے، لیکن انھوں نے میری بات نہیں مانی اور ہم واپس مدینہ آگئے۔ بعض سیرت نگاروں نے سریہ عبیدہ رضی اللہ عنہ کو پہلا اور سریہ حمزہ رضی اللہ عنہ کو دوسرا سریہ قرار دیا ہے۔(1)","",{"v":500350,"fn":"(1) السيرة لابن هشام: 591,592/2 ، المغازي للواقدي: 22/1 ، شرح الزرقاني على المواهب: 226-228/2"}],[2421,"§سریہ سعد بن ابی وقاص رضی اللہ عنہ\nتیسرا سریہ رسول اللہ صلی اللہ علیہ وسلم نے ہجرت کے 9 ماہ بعد ذی القعدہ میں الخرار کی جانب روانہ فرمایا، الخرار ایک وادی کا نام ہے۔ یہ جحفہ اور غدیر خم کے قریب ہے۔ اسی نسبت سے اسے سریہ الخرار بھی کہا جاتا ہے۔ آپ صلی اللہ علیہ وسلم نے اس لشکر کا امیر سعد بن ابی وقاص رضی اللہ عنہ کو مقرر فرمایا۔ اس لشکر کا جھنڈا بھی سفید تھا اور اسے اٹھانے کی سعادت مقداد بن عمرو بہرانی رضی اللہ عنہ کے حصے میں آئی جو لشکر کفار کی صفوں سے نکل کر سیدنا عبیدہ رضی اللہ عنہ کے لشکر میں شامل ہوگئے تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کے ہمراہ مہاجرین پر مشتمل 20 جنگجوؤں کا دستہ روانہ فرمایا۔ یہ سریہ ارسال کرنے کا مقصد\n[تصویر: وادی الخرار]\nبھی قریش کے تجارتی قافلے پر چھاپہ مارنا تھا۔ مسلمانوں کو قافلے کے تعاقب میں الخرار سے آگے نہ بڑھنے کی ہدایت کی گئی تھی۔\nسعد بن ابی وقاص رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا:\nاُخْرُجْ يَا سَعْدُ حَتَّى تَبْلُغَ الْخَرَّارَ، فَإِنَّ عِيرًا لِقُرَيْشٍ سَتَمُرُّ بِهِ","",{"v":500351,"im":["v5_p351.jpg"]}],[2422,"’’سعد! نکلو اور الخرار تک پہنچ جاؤ، قریش کے قافلے کا ادھر سے گزر ہوگا۔‘‘\nسعد رضی اللہ عنہ کہتے ہیں: میں بیس یا اکیس آدمیوں کے ساتھ پیدل ہی نکلا۔ ہم دن میں چھپے رہتے اور رات کو سفر کرتے حتیٰ کہ ہم پانچویں صبح وہاں پہنچے۔ یہاں ہمیں معلوم ہوا کہ جس قافلے کی طلب میں ہم نکلے تھے، وہ قافلہ گزشتہ روز گزر چکا ہے۔ چونکہ نبی صلی اللہ علیہ وسلم نے مجھ سے عہد لیا تھا کہ میں خرار سے تجاوز نہ کروں، لہٰذا میں نے واپس مدینہ کی راہ لی اور اگر یہ عہد نہ لیا ہوتا تو میں انھیں پانے کی امید رکھتا تھا۔(1)\nبعض سیرت نگاروں نے ان تینوں سرایا کو 2 ہجری کا واقعہ بتایا ہے۔ ان کے نزدیک پہلے غزوہ ودان یا ابواء وقوع پذیر ہوا، اس کے بعد سرایا بھیجے گئے۔","",{"v":500352,"fn":"(1) المغازي للواقدي: 23/1 ، شرح الزرقاني على المواهب: 228,229/2"}],[2423,"§غزوہ ابواء\nرسول اللہ صلی اللہ علیہ وسلم کا یہ پہلا غزوہ تھا۔ اسے غزوہ ابواء اور غزوہ ودان کے نام سے یاد کیا جاتا ہے۔ ہجرت کے تقریباً ایک سال بعد، ماہ صفر میں رسول اللہ صلی اللہ علیہ وسلم نے ابواء کی طرف پہلا سفر جہاد فرمایا۔ ابواء بحیرہ احمر کے ساحلی شہر مستورہ سے تقریباً 35 کلومیٹر مشرق میں وادی الفرع پر واقع ایک شہر تھا۔ اس سے تقریباً 6 یا 8 میل کے فاصلے پر دوسرا شہر ودان واقع تھا۔ لشکر کا جھنڈا سفید تھا جو سیدنا حمزہ رضی اللہ عنہ کو سونپا گیا۔ مدینہ پر سعد بن عبادہ رضی اللہ عنہ کو نائب مقرر کیا گیا اور سفر شروع ہوگیا۔ اس مہم کا مقصد بھی قریش کے تجارتی قافلے پر چھاپہ مار کارروائی کرنا تھا۔ لشکر میں تمام کے تمام مہاجرین شریک تھے۔ ان کی تعداد ساٹھ تھی۔ انصار کا کوئی فرد اس لشکر میں شریک نہ تھا۔ جب مسلمانوں کا یہ لشکر ابواء مقام پر پہنچا تو قریش کا قافلہ بچ نکلنے میں کامیاب ہوگیا تھا۔ اگرچہ اس قافلے پر قبضہ کرنے کا مقصد پورا نہ ہوسکا لیکن اس سے ایک اہم کام پایہ تکمیل کو پہنچا۔ وہ یہ تھا کہ اس علاقے میں بسنے والے قبیلے بنو ضمرہ کے سردار مخشی بن عمرو ضمری کے ساتھ باہمی معاہدہ طے پا گیا۔ اس معاہدے کا متن درج ذیل ہے:\nبِسْمِ اللَّهِ الرَّحْمٰنِ الرَّحِيمِ\nهٰذَا كِتَابٌ مِنْ مُحَمَّدٍ رَسُولِ اللَّهِ صلی اللہ علیہ وسلم لِبَنِي ضَمْرَةَ بِأَنَّهُمْ آمِنُونَ عَلَى أَمْوَالِهِمْ وَأَنْفُسِهِمْ، وَأَنَّ لَهُمُ النُّصْرَةَ عَلَى مَنْ رَامَهُمْ إِلَّا أَنْ يُحَارِبُوا فِي دِينِ اللَّهِ مَا بَلَّ بَحْرٌ صُوفَةً، وَأَنَّ النَّبِيَّ صلی اللہ علیہ وسلم إِذَا دَعَاهُمْ لِنَصْرِهِ أَجَابُوهُ، عَلَيْهِمْ بِذٰلِكَ ذِمَّةُ اللَّهِ وَذِمَّةُ رَسُولِهِ، وَلَهُمُ النُّصْرُ\n[تصویر: وادی ابواء]","",{"v":500353,"im":["v5_p353.jpg"]}],[2424,"[تصویر: نقشہ: غزوہ ابواء]\nاہم مقامات: مدینہ منورہ، المسیجید، الحمراء، بدر، الاکحل، وادی الفرع، ودان، الابواء، مستورہ، بنو ضمرہ، رابغ، خلیص، الجحفہ، عسفان، مکہ مکرمہ، حجاز، بحیرہ احمر (بحیرہ قلزم)۔ اشارات: رسول اللہ صلی اللہ علیہ وسلم کی پیش قدمی؛ قریش مکہ کا تجارتی قافلہ۔ وادی ابواء کی بستی ودان مدینہ سے تقریباً 250 کلومیٹر اور مستورہ سے تقریباً 12 کلومیٹر جنوب مشرق میں تھی۔\nعَلَى مَنْ بَرَّ مِنْهُمْ وَاتَّقَى\n’’اللہ کے نام سے جو بہت رحم کرنے والا اور نہایت مہربان ہے۔ یہ تحریر محمد رسول اللہ کی طرف سے بنی ضمرہ کے لیے لکھی گئی ہے، وہ امن سے رہیں گے، ان کے جان و مال محفوظ ہوں گے اور جو شخص ان پر حملہ کرنے کا ارادہ کرے گا، انھیں اس کے مقابلے میں مدد دی جائے گی بجز اس کے کہ وہ خود اللہ کے دین کے خلاف جنگ کریں۔ جب تک سمندر میں پانی کی ایک بوند بھی باقی رہے گی، یہ معاہدہ باقی رہے گا اور جب نبی صلی اللہ علیہ وسلم اپنی مدد کے لیے انھیں طلب کریں گے تو وہ حاضر ہوں گے۔ یہ ان کے ساتھ اللہ اور اس کے رسول کا عہد ہے اور جو شخص ان میں نیک اور پرہیزگار رہے گا، اس کی مدد کی جائے گی۔‘‘\nآپ صلی اللہ علیہ وسلم اس غزوے کے دوران 15 دن مدینہ سے باہر رہے اور پھر مدینہ واپس تشریف لے آئے۔(1)","",{"v":500354,"fn":"(1) شرح الزرقاني على المواهب: 229,230/2 ، الدرر لابن عبدالبر، ص: 90، المغازي للواقدي: 24/1، سبل الهدى والرشاد: 14/4 - الوثائق السياسية، ص: 267","im":["v5_p354.jpg"]}],[2425,"§غزوہ بواط\nیہ غزوہ ہجرت کے 13 ماہ بعد ربیع الاول یا ربیع الآخر میں پیش آیا۔ رسول اللہ صلی اللہ علیہ وسلم قریش کے تجارتی قافلے کو روکنے کی غرض سے 200 مہاجرین کے ساتھ بواط کی جانب نکلے۔ بواط جہینہ کے پہاڑوں میں سے ایک پہاڑ ہے جو ینبع کے قریب واقع ہے۔ مدینہ سے 4 برید (88.716 کلومیٹر)(1) کے فاصلے پر ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ میں اپنی نیابت کے لیے سعد بن معاذ یا سائب بن عثمان بن مظعون رضی اللہ عنہما کو مقرر فرمایا۔ لشکر کا جھنڈا سفید ہی تھا۔ اس دفعہ جھنڈا اٹھانے کی سعادت سعد بن ابی وقاص رضی اللہ عنہ کو حاصل ہوئی۔ اُدھر قریش کے تجارتی قافلے کی قیادت امیہ بن خلف کر رہا تھا۔ اس کے ساتھیوں کی تعداد 100 تھی۔ یہ قافلہ اڑھائی ہزار اونٹوں پر مشتمل تھا۔ رسول اللہ صلی اللہ علیہ وسلم مہاجرین کو ساتھ لیے جب بواط کے مقام پر پہنچے تو معلوم ہوا کہ قافلہ نکل گیا ہے، چنانچہ آپ صلی اللہ علیہ وسلم نے کوہ بواط\n[تصویر: وادی بواط]","",{"v":500355,"fn":"(1) معجم لغة الفقهاء، ص: 107","im":["v5_p355.jpg"]}],[2426,"[تصویر: نقشہ: غزوہ بواط (ربیع الآخر 2ھ)]\nاہم مقامات: مدینہ منورہ، وادی بواط، جبل رضوی، ینبع النخل، ینبع البحر، بحیرہ احمر (بحیرہ قلزم)، الحمراء، بدر، ام البرک، مستورہ، رابغ، خلیص، ودان، عسفان، حجاز، مہد الذہب، قرقرۃ الکدر۔ اشارات: رسول اللہ صلی اللہ علیہ وسلم کی پیش قدمی؛ امیہ بن خلف کا تجارتی قافلہ۔ پیمانہ: 0، 50، 100، 150 کلومیٹر۔\nکے لوگوں کے ساتھ معاہدہ فرمایا(1) اور بلا جدال و قتال مدینہ واپس آگئے۔(2)","",{"v":500356,"fn":"(1) رسول اکرم صلی اللہ علیہ وسلم کی سیاست خارجہ، ص: 191\n(2) شرح الزرقاني على المواهب: 232/2، سبل الهدى والرشاد: 15/4، المغازي للواقدي: 25/1","im":["v5_p356.jpg"]}],[2427,"§غزوہ سفوان\nیہ غزوہ بھی ہجرت کے 13 ماہ بعد ربیع الاول ہی میں پیش آیا۔ اس کی وجہ یہ تھی کہ مدینہ کے نواح میں ایک چراگاہ تھی جسے الجماء کہا جاتا تھا، وہاں مسلمانوں کے مویشی چرا کرتے تھے اور ایک آدھ چرواہا بھی ان کی نگرانی کے لیے مقرر ہوتا تھا۔ کفار مکہ نے اپنی دھمکیوں کو عملی جامہ پہنانے اور مسلمانوں پر دبدبہ بٹھانے کے لیے اپنے ایک سرکردہ شخص کرز بن جابر فہری کو چند افراد دے کر ایک مہم سونپی۔ وہ یہ کہ کرز بن جابر اس پارٹی کو ساتھ لے جائے اور مسلمانوں کی اس چراگاہ پر حملہ کرے۔ اس نے ایسا ہی کیا، درخت کاٹ دیے، چرواہے کو قتل کر دیا اور جتنے مویشی ہانک سکتا تھا، انھیں ساتھ لے بھاگا۔ رسول اللہ صلی اللہ علیہ وسلم کو جب اس واقعے کی اطلاع ملی تو آپ اپنے صحابہ کے ساتھ اس کے تعاقب میں نکلے۔ آپ نے مدینہ میں اپنی جگہ زید بن حارثہ رضی اللہ عنہ کو نائب مقرر کیا اور خود دشمن کے تعاقب میں وادی سفوان تک جا پہنچے۔ یہ وادی بدر کے بہت قریب تھی۔ انھی جگہوں کی مناسبت سے اسے غزوہ سفوان اور غزوہ بدر اولیٰ بھی کہا جاتا ہے۔ جب آپ صلی اللہ علیہ وسلم نے دیکھا کہ تعاقب بے سود ہے تو آپ نے واپس مدینہ کی راہ لی۔ اس مہم میں بھی مسلمانوں کا علم سفید تھا لیکن علمبردار سیدنا علی رضی اللہ عنہ تھے۔ غزوہ سفوان اور غزوہ ذی العشیرہ کی تاخیر و تقدیم میں اختلاف ہے۔(1)","",{"v":500357,"fn":"(1) سبل الهدى والرشاد: 16/4 - شرح الزرقاني على المواهب: 236/2 - المغازي للواقدي: 26/1"}],[2428,"[تصویر: نقشہ: غزوہ بدر سے پہلے کے غزوات و سرایا]\nاشارات: سریہ عبیدہ بن حارث (شوال 1ھ)، سریہ سعد بن ابی وقاص (ذی القعدہ 1ھ)، سریہ حمزہ بن عبدالمطلب (رمضان 1ھ)، غزوہ ودان، غزوہ ابواء، غزوہ بواط، غزوہ بدر اولیٰ، غزوہ ذی العشیرہ، سریہ عبداللہ بن جحش (رجب 2ھ)۔ اہم مقامات: مدینہ منورہ، عیص، جبل رضوی، ینبع، بدر، ابواء، وادی الفرع، خرار، رابغ، قدید، ذات عرق، قرن المنازل، عسفان، جدہ، مکہ مکرمہ، حجاز، بحیرہ قلزم (بحیرہ احمر)، نجد، مہد الذہب۔","",{"v":500358,"im":["v5_p358.jpg"]}],[2429,"§غزوہ ذی العشیرہ\nرسول اللہ صلی اللہ علیہ وسلم کو ہجرت کے دوسرے سال جمادی الاولیٰ کے شروع میں اطلاع موصول ہوئی کہ قریش کا ایک تجارتی قافلہ شام جا رہا ہے۔ ابوسفیان اس کی قیادت کر رہا ہے۔ یہ بہت بڑا تجارتی قافلہ ہے۔ تمام اہل مکہ نے اس میں بڑھ چڑھ کر سرمایہ کاری کی ہے اور اس کا مقصد حصول مال کے بعد مسلمانوں پر فیصلہ کن چڑھائی کرنا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے قافلے کے تعاقب کا فیصلہ کیا اور 150 یا 200 مہاجرین کے ساتھ مدینہ سے نکلے اور ذوالعشیرہ کا رخ فرمایا۔ ان تمام مہاجرین کے پاس اس سفر کے لیے 30 اونٹ میسر تھے جس پر سب باری باری سوار ہو رہے تھے۔ اس سفر کے لیے آپ صلی اللہ علیہ وسلم نے کسی کو نکلنے پر مجبور نہیں کیا۔ آپ صلی اللہ علیہ وسلم نے مدینہ میں اپنا نائب ابوسلمہ بن عبدالاسد رضی اللہ عنہ کو مقرر کیا۔ اس دفعہ جھنڈا سفید ہی تھا۔ جھنڈا اٹھانے کا شرف حمزہ بن عبدالمطلب رضی اللہ عنہ کے حصے میں آیا۔ رسول اللہ صلی اللہ علیہ وسلم اس لشکر کے ساتھ نقیب بن دینار کے راستے پر چلے اور فیفاء الخبار سے چلتے ہوئے بطحاء بن ازہر جسے ذات الساق بھی کہا جاتا ہے، کے مقام پر ایک درخت کے نیچے رکے جہاں آپ صلی اللہ علیہ وسلم کے لیے کھانا تیار کیا گیا۔ آپ صلی اللہ علیہ وسلم نے کھانا کھایا اور لوگوں نے بھی کھایا۔ پھر آپ صلی اللہ علیہ وسلم کو مشرب (مشیرب) نامی کنویں کا پانی پلایا گیا، پھر آپ صلی اللہ علیہ وسلم اور لشکر نے کوچ کیا۔ آپ خلائق کو بائیں\n[تصویر: بئر مشیرب]","",{"v":500359,"im":["v5_p359.jpg"]}],[2430,"جانب چھوڑتے ہوئے وادی عبداللہ کے راستے پر چلے حتیٰ کہ بلیل کے مقام پر اترے، پھر اسی راستے پر چلتے ہوئے آپ ینبع کے درمیان ذوالعشیرہ کے مقام پر جا ٹھہرے۔ ادھر پہنچ کر معلوم ہوا کہ قافلہ تو نکل چکا ہے۔ آپ صلی اللہ علیہ وسلم نے وہیں پڑاؤ کیا اور جمادی الاولیٰ کے باقی دن اور جمادی الآخرہ کے کچھ دن یہیں قیام فرمایا۔ قافلہ تو ہاتھ سے نکل گیا لیکن یہاں رہنے کا ایک عظیم فائدہ یہ ہوا کہ بنو مدلج اور بنو ضمرہ میں سے جو ان کے حلیف تھے، ان کے ساتھ انہی شرائط پر معاہدہ طے پا گیا جن شروط پر بنو ضمرہ کے ساتھ معاہدہ ہوا تھا۔ اس سے مسلمانوں کو اس علاقے میں بہت استحکام حاصل ہو گیا کیونکہ اب مشرکین مکہ سے لڑائی کے دوران اس علاقے والے ان کا ساتھ نہیں دے سکتے تھے۔ اگر ایسا نہ ہوتا تو کفار مسلمانوں کو مشکلات سے دوچار کر سکتے تھے۔ اس معاہدے کے بعد آپ صلی اللہ علیہ وسلم واپس مدینہ تشریف لے آئے۔ اسی غزوے کے موقع پر رسول اللہ صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ کو ابو تراب کے لقب سے نوازا جیسا کہ بعض علمائے کرام کا قول ہے۔(1)","",{"v":500360,"fn":"(1) السيرة لابن هشام: 598/2-600، سبل الهدى والرشاد: 17/4، شرح الزرقاني على المواهب: 232/2-235"}],[2431,"§سریہ عبداللہ بن جحش رضی اللہ عنہ\nہجرت کے سترھویں مہینے رجب میں رسول اللہ صلی اللہ علیہ وسلم نے عبداللہ بن جحش الاسدی رضی اللہ عنہ کی سرکردگی میں مہاجرین کا ایک دستہ روانہ فرمایا۔ اس دستے میں آٹھ یا بارہ مجاہد شامل تھے۔ عبداللہ بن جحش رضی اللہ عنہ فرماتے ہیں: اللہ کے رسول صلی اللہ علیہ وسلم نے نماز عشاء کے وقت مجھے بلایا اور حکم دیا کہ صبح کی نماز پڑھنے کے لیے مسلح ہو کر آنا اور مجھ سے ملنا۔ میں نے آپ کے حکم کی تعمیل کی۔ صبح کی نماز کے وقت مسلح ہو کر حاضر ہوا۔ میرے پاس تلوار، کمان، ترکش وغیرہ تھے۔ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے، صبح کی نماز پڑھائی اور پھر واپس چلنے لگے، میں پہلے ہی آپ کی آمد کا منتظر تھا۔ آپ کے دروازے پر کھڑا تھا۔ وہاں چند قریشی اور بھی موجود تھے۔ آپ صلی اللہ علیہ وسلم نے ابی بن کعب رضی اللہ عنہ کو بلایا تو وہ آپ کے پاس اندر تشریف لے گئے۔ آپ صلی اللہ علیہ وسلم نے انھیں ایک خط لکھنے کا حکم دیا جو انھوں نے تحریر کر دیا، پھر آپ صلی اللہ علیہ وسلم نے مجھے بلایا۔ وہ گرامی نامہ مجھے عطا کیا اور فرمایا: ’’میں نے ان لوگوں پر تمھیں امیر مقرر کیا ہے، تم انھیں ساتھ لے کر سفر پر روانہ ہو جاؤ۔ جب دو راتیں سفر کر چکو تو یہ خط کھول کر پڑھنا اور اس پر عمل کرنا۔‘‘ میں نے کہا: اے اللہ کے رسول! میں کس طرف سفر کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’نجدیہ کی طرف چل پڑو۔‘‘ یہ حکم سن کر عبداللہ بن جحش رضی اللہ عنہ آٹھ یا بارہ مہاجرین کو ساتھ لے کر روانہ ہو گئے۔ ان مہاجرین کے نام یہ تھے: 1 ابو حذیفہ بن عتبہ 2 عکاشہ بن محصن 3 عتبہ بن غزوان 4 سہیل بن بیضاء فہری 5 سعد بن ابی وقاص 6 عامر بن ربیعہ 7 واقد بن عبداللہ تمیمی 8 خالد بن بکیر لیثی رضی اللہ عنہ۔ بعض مؤرخین نے 9 عامر بن ایاس 10 مقداد بن عمرو 11 صفوان بن بیضاء رضی اللہ عنہم کا ذکر کیا ہے۔ مہاجرین کے اس دستے نے سفر شروع کیا، دو آدمی ایک اونٹ پر باری باری سفر کر رہے تھے۔ دو رات سفر کرنے کے بعد جب وہ ابن ضمیرہ کے کنویں کے پاس پہنچے تو وہاں انھوں نے حکم نامہ کھول کر پڑھا۔ اس میں تحریر تھا:\n«سِرْ حَتَّى تَأْتِيَ بَطْنَ نَخْلَةَ عَلَى اسْمِ اللَّهِ وَبَرَكَاتِهِ، وَلَا تُكْرِهَنَّ أَحَدًا مِنْ أَصْحَابِكَ عَلَى الْمَسِيرِ مَعَكَ، وَامْضِ لِأَمْرِي فِيمَنْ تَبِعَكَ حَتَّى تَأْتِيَ بَطْنَ نَخْلَةَ، فَتَرَصَّدْ بِهَا عِيرَ قُرَيْشٍ وَتُعْلِمَ لَنَا مِنْ أَخْبَارِهِمْ»","",{"v":500361}],[2432,"[تصویر: وادی نخلہ یمانیہ]\n’’اللہ کے نام اور اس کی برکت سے سفر جاری رکھو حتیٰ کہ تم بطن نخلہ تک پہنچ جاؤ، اپنے ساتھیوں میں سے کسی کو اپنے ساتھ چلنے پر مجبور نہ کرنا۔ جب تم اور تمھاری پیروی کرنے والے میرے حکم کے مطابق چلتے ہوئے بطن نخلہ تک پہنچ جائیں تو وہاں پہنچ کر قریش کے قافلے کا انتظار کرنا اور ان کے بارے میں ہمیں مطلع کرنا۔‘‘ عبداللہ بن جحش نے یہ حکم نامہ پڑھا تو کہا: سَمْعًا وَطَاعَةً، ’’میں بسر و چشم حاضر ہوں۔‘‘ پھر انھوں نے اس بات کی خبر اپنے ساتھیوں کو دی اور انھیں بتایا کہ میں کسی کو اپنے ساتھ چلنے پر مجبور نہیں کرتا۔ جو چلنا چاہتا ہے وہی چلے۔ میں تو آپ صلی اللہ علیہ وسلم کے حکم کی تعمیل میں چلوں گا، کوئی چلے یا نہ چلے۔ جس کو شہادت پسند ہے، وہ چلے اور جو موت کو پسند نہیں کرتا، وہ لوٹ جائے۔ ان سب نے کہا: ہم سب اس چیز کی رغبت اور شوق رکھتے ہیں جس کا تم شوق رکھتے ہو اور ہم میں سے ہر ایک دل و جان سے اللہ کے رسول کے حکم کے سامنے سر تسلیم خم کیے ہوئے ہے، چنانچہ یہ دستہ بطن نخلہ کی جانب روانہ ہو گیا۔ اس سے پہلے کہ یہ مہاجرین بطن نخلہ پہنچتے، راستے میں ان کے دو ساتھی سعد بن ابی وقاص اور عتبہ بن غزوان رضی اللہ عنہما کا اونٹ گم ہو گیا تو وہ پیچھے رہ گئے، چنانچہ جب یہ لوگ بطن نخلہ پہنچے تو وہاں قریش کے قافلے کو پہلے ہی موجود پایا جو اپنے ساز و سامان سمیت وہاں موجود تھا۔ ان میں عمرو بن حضرمی، حکم بن کیسان مخزومی، نوفل بن عبداللہ مخزومی، عثمان بن عبداللہ مخزومی بھی شامل تھے۔ یہ لوگ مسلمانوں کو دیکھ کر گھبرا گئے اور فوراً چوکنے ہو گئے۔ اس موقع پر عکاشہ بن محصن رضی اللہ عنہ نے یہ ظاہر کرنے کے لیے کہ وہ عمرہ ادا کرنے جا رہے ہیں اور لڑائی کا ارادہ نہیں رکھتے، اپنا سر منڈا دیا۔ انھیں اس حالت میں دیکھ کر مشرکین کو","",{"v":500362,"im":["v5_p362.jpg"]}],[2433,"کو تسلی ہو گئی، لہٰذا انھوں نے اپنے سواری کے جانوروں کو رسیوں سے باندھ کر چرنے کے لیے چھوڑ دیا۔ اب مسلمان آپس میں مشورہ کرنے لگے کہ کیا کیا جائے؟ ایک تو یہ رجب کا آخری دن تھا اور رجب حرمت والے مہینوں میں سے ہے۔ اس میں جنگ کرنا منع ہے اور اگر آج انھیں چھوڑ دیا گیا تو کل یہ حدود حرم میں داخل ہو جائیں گے۔ حدود حرم میں بھی لڑائی منع ہے۔ اس لحاظ سے تو ہم انھیں کچھ بھی نہیں کہہ سکیں گے۔ آخر اکثریت رائے سے فیصلہ یہ ہوا کہ قافلے کو جانے نہ دیا جائے بلکہ ان پر دھاوا بولا جائے۔ اب واقد بن عبداللہ رضی اللہ عنہ نکلے۔ وہ بہت زبردست تیرانداز تھے۔ انھوں نے تاک کر عمرو بن حضرمی کو تیر مارا جس سے اس کا کام تمام ہو گیا اور باقی مجاہدین نے مشرکین پر ہلہ بول دیا۔ عثمان بن عبداللہ مخزومی اور حکم بن کیسان کو گرفتار کر لیا گیا۔ سامان تجارت سے لدے ہوئے اونٹوں پر بھی مسلمانوں نے قبضہ کر لیا۔ عبداللہ بن جحش رضی اللہ عنہ دو قیدیوں اور تجارتی اونٹوں کو ساتھ لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس مدینہ پہنچ گئے۔ رسول اللہ صلی اللہ علیہ وسلم کو جب اس صورت حال سے آگاہی ہوئی تو آپ صلی اللہ علیہ وسلم سخت ناراض ہوئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: «مَا أَمَرْتُكُمْ بِالْقِتَالِ فِي الشَّهْرِ الْحَرَامِ» ’’میں نے تمھیں حرمت والے مہینے میں لڑنے کے لیے نہیں کہا تھا۔‘‘ آپ صلی اللہ علیہ وسلم نے سامان اور قیدی قبول کرنے سے انکار کر دیا۔ فوجی دستہ سہم گیا کہ ہم تو مارے گئے۔ ہمارے دونوں جہان دنیا و آخرت برباد ہو گئے۔ مسلمان بھائیوں نے بھی ان کو طعن و تشنیع کا نشانہ بنایا۔ اُدھر قریش نے واویلا کیا کہ محمد (صلی اللہ علیہ وسلم) اور اس کے ساتھیوں نے تو اب حرمت کے مہینے کو بھی بے حرمت کر دیا ہے، ان کی عزت خاک میں ملا دی ہے۔ الزام تراشیوں کا ایک طوفان امڈ آیا۔ ان حالات کو دیکھ کر مجاہدین کے غم و اندوہ کی انتہا ہو گئی تو اللہ تعالیٰ نے رسول اللہ صلی اللہ علیہ وسلم پر یہ آیات نازل فرمائیں:\n﴿يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ ۖ قُلْ قِتَالٌ فِيهِ كَبِيرٌ ۖ وَصَدٌّ عَنْ سَبِيلِ اللَّهِ وَكُفْرٌ بِهِ وَالْمَسْجِدِ الْحَرَامِ وَإِخْرَاجُ أَهْلِهِ مِنْهُ أَكْبَرُ عِنْدَ اللَّهِ ۚ وَالْفِتْنَةُ أَكْبَرُ مِنَ الْقَتْلِ ۗ وَلَا يَزَالُونَ يُقَاتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَنْ دِينِكُمْ إِنِ اسْتَطَاعُوا﴾\n(اے نبی!) یہ آپ سے حرمت والے مہینے کے بارے میں پوچھتے ہیں کہ اس میں لڑائی کیسی ہے؟ کہہ دیجیے: اس میں لڑنا بہت بڑا (گناہ) ہے اور اللہ کی راہ سے لوگوں کو روکنا اور اس کے ساتھ کفر کرنا اور مسجد الحرام سے (روکنا) اور حرم کے رہنے والوں کو وہاں سے نکالنا اللہ کے نزدیک اس سے بھی بڑا (گناہ) ہے۔ اور فتنہ انگیزی قتل سے کہیں بڑا گناہ ہے۔ وہ تو تم سے لڑتے ہی جائیں گے حتیٰ کہ اگر ان کا بس چلے تو تمھارے دین سے تم کو پھیر لے جائیں۔(1)","",{"v":500363,"fn":"(1) البقرة 2:217"}],[2434,"ان آیات مقدسہ کے نزول کے بعد رسول اللہ صلی اللہ علیہ وسلم نے اس مال اور قیدیوں کو قبول کیا اور مال غنیمت میں سے خمس (پانچواں حصہ) لیا۔ یہ پہلی غنیمت میں سے پہلا خمس تھا جو بعد میں فرض کر دیا گیا۔ جب قریش نے اپنے دو جنگی قیدیوں کو چھڑانے کے لیے نامہ و پیام شروع کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ بات چیت ہمارے دو آدمی سعد بن ابی وقاص اور عتبہ بن غزوان کی واپسی کے بعد ہی ہو سکتی ہے۔‘‘ آپ کو خطرہ تھا مبادا قریش انھیں نقصان پہنچائیں۔ کچھ دنوں بعد سعد اور عتبہ بخیریت واپس آ گئے، پھر رسول اللہ صلی اللہ علیہ وسلم نے ان دونوں قیدیوں کا فدیہ چالیس اوقیہ چاندی فی کس لے کر انھیں آزاد کر دیا۔\nان میں سے حکم بن کیسان نے اسلام قبول کر لیا۔ بعد ازاں وہ شرعی احکام کو حسن و خوبی سے انجام دیتے رہے یہاں تک کہ بئر معونہ کے حادثے میں انھوں نے جام شہادت نوش کیا۔ دوسرا قیدی عثمان بن عبداللہ مکہ واپس آ گیا، وہ کفر ہی پر ڈٹا رہا اور حالت کفر ہی میں اسے موت آئی۔ اس سریہ کو سریہ نخلہ بھی کہا جاتا ہے۔(1)","",{"v":500364,"fn":"(1) المغازي للواقدي: 28/1-32، الدرر لابن عبدالبر، ص: 97-99، شرح الزرقاني على المواهب: 237/2-242"}],[2435,"باب 7\n§غزوہ بدر الکبریٰ\nحق و باطل کا وہ پہلا معرکہ جس نے مشرکین مکہ کا غرور خاک میں ملا کر ہمیشہ کے لیے باطل کی شکست و ہزیمت کا دروازہ کھول دیا","",{"v":500365}],[2436,"﴿وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ﴾\n’’اور اللہ نے بدر میں تمھاری مدد کی۔‘‘\n(آل عمران 3:123)","",{"v":500366}],[2437,"§اس باب میں\nآپ کو معلوم ہوگا کہ اللہ تعالیٰ نے غزوہ بدر میں ناتواں مسلمانوں کو رؤسائے مکہ پر فتح یاب فرما کر دین حق کی فتح اور باطل کی دائمی شکست و ذلت کے دروازے کھول دیے۔ اسی لیے قرآن کریم نے اسے یوم الفرقان، یعنی حق و باطل میں امتیاز کرنے والی جنگ قرار دیا ہے۔ ابوسفیان شام سے بھاری مال و متاع لے کر واپس مکہ مکرمہ آ رہا تھا۔ اُسے اثنائے راہ میں بعض شواہد کی بنا پر یقین ہو گیا کہ مسلمان اُس کے قافلے کی گھات میں ہیں۔ اُس نے فوراً ضمضم بن عمرو غفاری کو مکہ کی طرف دوڑایا اور قریش کو پیغام بھیجا کہ قافلہ خطرے میں ہے، اس کے بچاؤ کا انتظام کر لو۔ بعد ازاں ابوسفیان راستہ بدل کر اپنا قافلہ صحیح سلامت بچا لے گیا۔ اُدھر ابوجہل مسلمانوں سے مقابلے کے لیے بھاری لشکر لے کر مکہ سے نکل پڑا۔ اس لشکر کو راستے ہی میں اطلاع مل گئی کہ اُن کا قافلہ سلامت ہے، اسے کوئی گزند نہیں پہنچا، چنانچہ بہت سے شرکائے لشکر نے کہا کہ اب پیش قدمی کی کوئی ضرورت نہیں، واپس چلنا چاہیے۔ ابوجہل اڑ گیا، کہنے لگا کہ اب ہمارا لشکر پیچھے نہیں ہٹے گا، بدر جا کر ہی دم لے گا اور مسلمانوں کو ہلاک کر کے واپس آئے گا۔ بس یہی وہ مرحلہ تھا جب رؤسائے مکہ نے اپنی ہلاکت کے راستے پر قدم بڑھا دیے اور بدر کے میدان میں مسلمانوں کے ہاتھوں مارے گئے۔ ان حالات و واقعات کے تفصیلی مطالعے سے آپ پر جو سب سے بڑی حقیقت آشکار ہوگی، وہ یہ ہے کہ جب بھی مسلمان بدری صحابہ جیسے ایمان و یقین سے مالا مال ہوں گے، اللہ تعالیٰ انھیں بڑے سے بڑے دشمن پر غلبہ عطا کر کے ہر محاربے میں فتح یاب فرمائے گا۔ مولانا ظفر علی خان نے کیا خوب کہا ہے:\n§فضائے بدر پیدا کر فرشتے تیری نصرت کو\nاتر سکتے ہیں گردوں سے قطار اندر قطار اب بھی","",{"v":500367}],[2438,"§یومِ فرقان\nاب تک آپ نے رسالت مآب صلی اللہ علیہ وسلم کی سیرت مبارک کے جتنے حالات پڑھے ہیں ان کی روشنی میں غور کیجیے کہ رسول اللہ صلی اللہ علیہ وسلم اور مشرکین مکہ کے مابین سارا جھگڑا کس بات پر تھا؟ صرف اسی بات پر کہ رسالت مآب صلی اللہ علیہ وسلم ایک اللہ کی بندگی کی دعوت دیتے اور فرماتے تھے کہ میں لَا إِلَٰهَ إِلَّا اللَّه کی حقیقت عظمیٰ اور سچائی کی روشن دلیلیں لے کر آیا ہوں۔ میری دعوت قبول کر لو۔ تمھیں دنیا اور آخرت دونوں جہانوں میں عزت، کامیابی اور سرفرازی نصیب ہوگی۔ اس دعوت کے جواب میں مشرکین مکہ کہتے تھے کہ ہم آپ کو یہ دعوت پھیلانے کی اجازت نہیں دیں گے۔ وہ انسان کے لیے اظہار رائے اور ضمیر و اعتقاد کی آزادی کا حق تسلیم نہیں کرتے تھے۔ وہ علم و بصیرت کو فکر و عمل کی بنیاد ماننے سے انکار کرتے تھے۔ آباء و اجداد کی اندھی تقلید کے قائل تھے۔ وہ مسلمانوں پر ظلم و ستم کرتے تھے اور تلوار کے زور پر انھیں عقیدہ توحید سے ہٹا کر شرک و بت پرستی کی طرف واپس لانا چاہتے تھے۔\nرسول اللہ صلی اللہ علیہ وسلم اور مسلمان سالہا سال مشرکین مکہ کے وحشیانہ مظالم سہتے رہے۔ وہ ایک لمحے کے لیے بھی اپنے وحدہ لاشریک پروردگار کی پرستش سے پیچھے نہیں ہٹے اور دین حنیف کی تبلیغ و دعوت سے کبھی باز نہیں آئے۔ جب کمزور اور مظلوم مسلمانوں پر مشرکین کے سنگین مظالم آئے دن بڑھتے ہی چلے گئے تو آپ صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم کو حبشہ کی طرف ہجرت کی اجازت دے دی، پھر جب نوبت یہاں تک آگئی کہ مشرکین صدائے توحید کو ہمیشہ\n[تصویر: حبشہ (موجودہ اریٹیریا) کی بندرگاہ مصوع]","",{"v":500368,"im":["v5_p368.jpg"]}],[2439,"کے لیے خاموش کرنے اور آپ صلی اللہ علیہ وسلم کو قتل کرنے پر تل گئے تو آپ صلی اللہ علیہ وسلم نے بھی اپنے محبوب وطن مکہ کو خیرباد کہا اور ہجرت فرما کر مدینہ چلے آئے۔\nرسول اللہ صلی اللہ علیہ وسلم اور جملہ فرزندانِ توحید مکہ سے نکل کر مدینہ آئے۔ اب تو مشرکین مکہ کو چین آ جانا چاہیے تھا۔ یہ لوگ اللہ کے دشمن تھے۔ انھیں چین نہیں آیا۔ یہ حق دشمنی کی انتہا تھی کہ رؤسائے مکہ نے پہلے نجاشی کے پاس تحائف بھیج کر مسلمانوں کو حبشہ سے نکلوانے کی مذموم کوشش کی اور اب جبکہ رسول اللہ صلی اللہ علیہ وسلم اور جملہ صحابہ کرام رضی اللہ عنہم مدینہ میں مقیم ہو گئے تو انھوں نے عبداللہ بن ابی اور اس کے ساتھیوں سے ساز باز کی اور انھیں خط لکھا کہ تم نے ہمارے جس آدمی کو اپنے ہاں ٹھہرا لیا ہے، اُسے نکال دو ورنہ ہم تم پر حملہ کر دیں گے، تمھارے نوجوانوں کو قتل کر ڈالیں گے اور تمھاری عورتوں کو اپنے قبضے میں لے کر لونڈیاں بنا لیں گے۔ انھوں نے اس دھمکی کو عملی جامہ پہنانے کے لیے جارحیت کا آغاز بھی کر دیا۔ قریش کا ایک سردار کرز بن جابر الفہری ایک دن مدینہ پہنچا۔ وہاں میدان میں اونٹ چر رہے تھے، وہ انھیں ہانک کر لے گیا۔ مسلمانوں نے اس کا پیچھا کیا مگر وہ بچ کر نکل گیا۔ یہ اقدام درحقیقت اس بات کا اعلان تھا کہ مشرکین مکہ مسلمانوں کو مدینہ میں بھی آرام سے نہیں بیٹھنے دیں گے۔ رؤسائے مکہ نے مدینہ کے معاہدہ شکن اور غدار یہودیوں کو بھی اپنے ساتھ ملا لیا اور مسلمانوں کو کہلا بھیجا کہ مکہ سے تو تم صحیح سلامت نکل آئے لیکن اب تمھاری خیر نہیں، ہم تمھیں مدینہ میں بھی نہیں چھوڑیں گے۔\n§رسول اللہ صلی اللہ علیہ وسلم کی دلیری و استقامت\nان حالات میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے صرف دو راہیں تھیں یا تو آپ صلی اللہ علیہ وسلم دعوتِ الی اللہ ترک کر دیں یا مشرکین مکہ کے چیلنج کا مقابلہ کریں۔ آپ صلی اللہ علیہ وسلم کا تو مقصدِ حیات ہی بنی نوع انسان کو اللہ تعالیٰ کا پیغام پہنچانا تھا، اس لیے آپ صلی اللہ علیہ وسلم نے بلا تامل مشرکین مکہ کے جارحانہ ارادوں کا ڈٹ کر مقابلہ کرنے کا فیصلہ کر لیا۔ یوں ہمیشہ کے لیے بتا دیا کہ حالات چاہے کتنے ہی کٹھن اور جان لیوا ہوں، راہِ حق کے راہیوں کو صرف صراطِ مستقیم پر چلنا چاہیے۔ اب دیکھیے رسالت مآب صلی اللہ علیہ وسلم نے مشرکین مکہ کا مقابلہ اللہ رب العزت پر کس قدر زبردست یقین اور کتنی بے مثل فراست و استقامت سے کیا۔ اور مجاہدین اسلام کو قرآن کریم کی تعلیمات کے مطابق درج ذیل انتہائی اہم اصول و مبادیات ذہن نشین کرائے:\n1 ثابت قدم رہو کیونکہ ثابت قدم رہنے والے ہی میدانِ جنگ میں فتح یاب ہوتے ہیں۔\n2 اللہ رب العزت کو بہت یاد کرو۔ اس طرح تمھارا ایمان محکم اور دل بہت مضبوط رہے گا۔","",{"v":500369}],[2440,"3 اللہ اور اس کے رسول کی اطاعت کرو۔ بعد ازاں اپنے سربراہِ حکومت کی صحیح باتوں میں اطاعت کرو کیونکہ ڈسپلن کے بغیر کوئی جماعت کامیاب نہیں ہو سکتی۔\n4 آپس میں لڑائی جھگڑے سے بچو ورنہ سست ہو جاؤ گے اور بات بگڑ جائے گی۔\n5 کتنے ہی کٹھن مصائب و مشکلات پیش آئیں صبر سے جھیلتے رہو۔ بالآخر جیت اُسی کی ہوتی ہے جو صبر و استقامت کا مظاہرہ کرتا ہے۔\n6 کافروں کے طور طریقے ہرگز اختیار نہ کرو کیونکہ وہ ایمان اور صراطِ مستقیم کے برعکس گھمنڈ اور نمود و نمائش کے طریقے اپناتے ہیں۔ تمھارے سارے کاموں کی بنیاد اللہ تعالیٰ کی سچی بندگی اور عجز و اخلاص پر ہونی چاہیے۔\n§مسلمانوں پر یلغار کے لیے مشرکین مکہ کی منصوبہ بندی\nمشرکین مکہ نے مسلمانوں کو صفحۂ ہستی سے مٹانے کا فیصلہ کر لیا اور ان پر چڑھائی کی تیاری شروع کر دی۔ اتنے بڑے منصوبے کے لیے یقیناً خطیر رقم کی ضرورت تھی، چنانچہ اہل مکہ نے ابوسفیان (رضی اللہ عنہ) کی قیادت میں ایک تجارتی قافلہ تیار کیا جس میں مکہ کے ہر فرد نے مقدور بھر حصہ ڈالا۔\n§قافلے کی مالیت\nاس قافلے میں اہل مکہ کی بڑی دولت تھی، یعنی ایک ہزار اونٹ جن پر کم از کم پچاس ہزار دینار (262.5 کلو سونے) کی مالیت کا ساز و سامان لدا ہوا تھا۔ اہل مدینہ کے لیے یہ بڑا سنہری موقع تھا۔ خصوصاً ان مہاجرین کے لیے جن کے اموال اور جائداد پر مشرکین مکہ نے قبضہ کر لیا تھا جبکہ اہل مکہ کے لیے اس مالِ فراواں سے محرومی بڑی زبردست فوجی، سیاسی اور اقتصادی چوٹ تھی۔(1) اس قافلے میں مخرمہ بن نوفل اور عمرو بن عاص بن وائل بھی تھے۔\n[تصویر: ینبع النخل کے قریب قدیم و جدید ذی العشیرہ]","",{"v":500370,"fn":"(1) سبل الهدى والرشاد: 18/4، الرحيق المختوم، ص: 279","im":["v5_p370.jpg"]}],[2441,"نبی اکرم صلی اللہ علیہ وسلم کو اس کی خبر ہوئی تو آپ صلی اللہ علیہ وسلم جمادی الاولیٰ یا آخرہ 2ھ، نومبر، دسمبر 623ء میں تقریباً ڈیڑھ دو سو صحابہ کو لے کر اس قافلے کو روکنے کے لیے نکلے۔ جب آپ صلی اللہ علیہ وسلم ’’العشیرہ‘‘ نامی جگہ پر پہنچے تو پتہ چلا کہ قافلہ شام کی طرف جا چکا ہے، لہٰذا آپ واپس آ گئے۔\nبعد ازاں رسول اللہ صلی اللہ علیہ وسلم کو علم ہوا کہ ابوسفیان کی قیادت میں بڑا بھاری تجارتی قافلہ اب شام سے مکہ کی طرف روانہ ہو چکا ہے اور اس کی حفاظت کے لیے تیس سے چالیس افراد کا دستہ متعین ہے۔\n§قافلے کی جاسوسی\nرسول اللہ صلی اللہ علیہ وسلم نے اس قافلے کی جاسوسی کے لیے سیدنا طلحہ بن عبیداللہ اور سیدنا سعید بن زید رضی اللہ عنہما کو بھیجا۔ وہ بندرگاہ الحوراء کے قریب نخبار نامی ساحلی مقام پر کشد جہنی کے ہاں ٹھہرے۔ اس نے انھیں اپنی پناہ میں رکھا۔ وہ اسی کے پاس خیمے میں رہے یہاں تک کہ قافلہ وہاں سے گزرا۔ ان دونوں ساتھیوں نے قافلے کے افراد اور ساز و سامان کو دیکھا۔ اُدھر قافلے والوں نے کشد جہنی سے پوچھا: اے کشد! کیا تو نے یہاں محمد (صلی اللہ علیہ وسلم) کے جاسوسوں کو دیکھا ہے؟ اس نے کہا: اللہ کی پناہ! محمد (صلی اللہ علیہ وسلم) کے جاسوسوں کا نخبار میں کیا کام؟ جب قافلے والے مطمئن ہو گئے تو ان دونوں نے رات بسر کی اور صبح ہوتے ہی وہاں سے نکل پڑے۔\n[تصویر: الحوراء (اُملج) کی بندرگاہ]","",{"v":500371,"im":["v5_p371.jpg"]}],[2442,"[تصویر: ذوالمروہ کا علاقہ]\nکشد بھی ان کے ساتھ آیا اور انھیں ساحل کے قریب ’’ذوالمروہ‘‘ نامی جگہ تک چھوڑ گیا۔ مکی قافلہ بھی تیزی سے سفر طے کر رہا تھا۔ اہل قافلہ نے شب کی تاریکی اور دن کے اجالے میں برابر سفر جاری رکھا۔ ابوسفیان کو برابر یہ خوف لاحق تھا کہ کہیں قافلے پر حملہ نہ ہو جائے۔ وہ قدم قدم پر محمدی سپاہ کی خبر لے رہا تھا۔(1)\nابن سعد نے ذکر کیا ہے کہ طلحہ بن عبیداللہ اور سعید بن زید رضی اللہ عنہما جب ابوسفیان کے قافلے کی خبر لے کر آئے تو انھیں پتہ چلا کہ رسول اللہ صلی اللہ علیہ وسلم مدینہ سے روانہ ہو چکے ہیں۔(2) واقدی نے ذکر کیا ہے کہ یہ اس دن مدینہ پہنچے جب بدر میں رسول اللہ صلی اللہ علیہ وسلم کا کفار سے آمنا سامنا ہوا اور ان کی ملاقات آپ صلی اللہ علیہ وسلم سے تربان نامی مقام پر ہوئی۔(3)\n[تصویر: وادی تربان]","",{"v":500372,"fn":"(1) المغازي للواقدي: 33,34/1\n(2) الطبقات لابن سعد: 11,12/2\n(3) المغازي للواقدي: 34/1","im":["v5_p372.jpg"]}],[2443,"جبکہ حافظ ابن حجر رحمہ اللہ نے ذکر کیا ہے کہ دونوں صحابہ کے واپس آنے سے پہلے لڑائی ہو چکی تھی۔ نبی صلی اللہ علیہ وسلم نے انھیں بدر میں شریک ہونے والوں کے ساتھ ملا دیا اور انھیں مال غنیمت میں سے حصہ عطا فرمایا اور ان کا اجر بھی بیان فرمایا۔(1)\nرسول اللہ صلی اللہ علیہ وسلم کی صحابہ کرام رضی اللہ عنہم کو مکی قافلہ روکنے کی ترغیب\nرسول اللہ صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم کو قافلے کا پیچھا کرنے کی دعوت دی لیکن اس میں شرکت کو ضروری قرار نہ دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا:\n«هَٰذِهِ عِيرُ قُرَيْشٍ، فِيهَا أَمْوَالُهُمْ، فَاخْرُجُوا إِلَيْهَا، لَعَلَّ اللَّهَ يُنْفِلُكُمُوهَا» ’’یہ قریش کا قافلہ ہے، اس میں ان کے اموال ہیں۔ اس کی طرف نکلو، ممکن ہے اللہ تعالیٰ تمھیں وہ قافلہ بطور غنیمت عطا فرما دے۔‘‘(2)\nصحیح مسلم میں ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\n«إِنَّ لَنَا طَلِبَةً فَمَنْ كَانَ ظَهْرُهُ حَاضِرًا فَلْيَرْكَبْ مَعَنَا» ’’بے شک ہم ایک چیز حاصل کرنا چاہتے ہیں، چنانچہ جس کی سواری حاضر ہو، وہ ہمارے ساتھ سوار ہو جائے۔‘‘ بعض لوگوں نے عوالی مدینہ سے اپنی سواریاں لانے کی اجازت مانگی، آپ صلی اللہ علیہ وسلم نے انھیں سواریاں لانے سے منع فرما دیا۔(3)\nرسول اللہ صلی اللہ علیہ وسلم اس وقت قطعاً لڑائی کی نیت سے روانہ نہیں ہوئے تھے۔ آپ تو صرف قریش کے تجارتی قافلے کو روکنے کے لیے روانہ ہوئے تھے۔ یہ توقع ہی نہیں تھی کہ قافلے کے بجائے لشکرِ قریش کے ساتھ میدانِ بدر میں نڈ بھیڑ ہو جائے گی۔ یہی وجہ ہے کہ بہت سے صحابہ کرام رضی اللہ عنہم مدینے ہی میں رہ گئے۔ ان کا خیال تھا کہ نبی صلی اللہ علیہ وسلم کا یہ سفر عام فوجی مہمات سے مختلف نہ ہوگا، اس لیے اس غزوے سے پیچھے رہنے والوں سے کوئی باز پرس نہ کی گئی۔(4) جب آپ صلی اللہ علیہ وسلم نے صحابہ کو مکی قافلہ روکنے کی دعوت دی تو انھوں نے آپ کا یہ فرمان سن کر ترغیب کو قبول کیا۔ بعض تو فوراً اٹھ کھڑے ہوئے اور بعض نے قدرے سستی کی۔ اس کا سبب یہ تھا کہ انھوں نے یہ خیال کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ نہیں فرمایا کہ جنگ درپیش ہے۔(5)","",{"v":500373,"fn":"(1) فتح الباري: 388/7\n(2) السيرة لابن هشام: 606,607/2\n(3) صحيح مسلم: 1901\n(4) صحيح البخاري: 4418\n(5) السيرة لابن هشام: 607/2"}],[2444,"اگر صحابہ کرام رضی اللہ عنہم کو یہ معلوم ہوتا کہ رسول اکرم صلی اللہ علیہ وسلم کی فوج سے سخت لڑائی کریں گے تو ان میں سے کوئی جنگجو بھی پیچھے نہ رہتا بلکہ توقع یہ تھی کہ قافلے کے تین یا چالیس محافظ آپ صلی اللہ علیہ وسلم کے تین سو سے زائد جاں نثاروں کو دیکھتے ہی بھاگ نکلیں گے۔ اس حقیقت کو ایک انصاری سردار سیدنا اسید بن حضیر رضی اللہ عنہ کے بیان کی روشنی میں دیکھیے جب وہ نبی صلی اللہ علیہ وسلم کو فتح کی مبارک باد دینے کے لیے آئے تو کہنے لگے: اے اللہ کے رسول! تمام تعریفیں اس ذات کے لیے ہیں جس نے آپ کو کامیابی سے نوازا اور آپ کی آنکھیں ٹھنڈی کیں۔ اے اللہ کے رسول! اللہ کی قسم! اگر مجھے خیال ہوتا کہ آپ دشمن سے جنگ کریں گے تو میں بدر سے ہرگز پیچھے نہیں رہ سکتا تھا بلکہ میں نے سوچا کہ وہ محض ایک قافلہ ہے۔ اگر مجھے پتہ ہوتا کہ وہ دشمن ہے تو میں پیچھے نہ رہتا۔ آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: ’’تم نے سچ کہا۔‘‘(1)\n[تصویر: مسجد اسید بن حضیر، حلب (شام)]\nسیدنا کعب بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ اللہ کے رسول صلی اللہ علیہ وسلم نے جتنی جنگیں لڑیں، میں غزوہ تبوک کے سوا ان سب میں شریک ہوا، البتہ غزوہ بدر میں شریک نہ ہو سکا۔ لیکن جو لوگ اس غزوے میں شریک نہ ہو سکے تھے، ان میں سے کسی پر اللہ تعالیٰ نے عتاب نازل نہیں کیا کیونکہ رسول اللہ صلی اللہ علیہ وسلم قریش کے قافلے کو تلاش کرنے کے لیے نکلے تھے مگر اللہ تعالیٰ نے ناگہانی مسلمانوں کو ان کے دشمنوں سے بھڑا دیا۔(2)\n§ایک غلط فہمی اور اس کا ازالہ\nبعض مستشرقین اور ان سے متاثر لوگ رسول اللہ صلی اللہ علیہ وسلم کی اس کارروائی کو ڈکیتی اور لوٹ مار سے تعبیر کرتے ہیں۔ درحقیقت اس خیال کی بنیاد وہ کینہ ہے جو آنکھوں پر تعصب کی پٹی باندھ دیتا ہے اور انسان کو حقائق سے اندھا کر دیتا ہے اور انسان اپنی خواہشات کا بندہ بن جاتا ہے۔ مسلمانوں اور کفار کے درمیان دشمنی اور جنگ کی فضا بدستور قائم تھی۔ جن لوگوں نے ظلم و سرکشی سے اسلام اور مسلمانوں کو صفحہ ہستی سے مٹانے کا اعلان کیا تھا، وہ اہل مکہ اور اس قافلے والے لوگ ہی تھے۔ یہی وہ لوگ تھے جنھوں نے مہاجرین کے اموال اور مملوکات پر صرف اس","",{"v":500374,"fn":"(1) المغازي للواقدي: 34,35/1، دلائل النبوة للبيهقي: 133/3\n(2) صحيح البخاري: 3951","im":["v5_p374.jpg"]}],[2445,"وجہ سے قبضہ کر لیا تھا کہ انھوں نے طرح طرح کے جھوٹے خداؤں کو چھوڑ کر ایک اللہ کی بندگی کیوں اختیار کر لی ہے اور کیوں انھوں نے محمد رسول اللہ صلی اللہ علیہ وسلم کو اپنا قائد تسلیم کر لیا ہے۔\nچنانچہ اہل مکہ کے اس قسم کے ہتھکنڈوں کی وجہ سے مظلوم مسلمانوں کو یہ حق حاصل تھا کہ وہ اعلانِ جنگ کرنے والوں سے لڑیں اور دشمن کا جو کچھ ہاتھ لگے، اس پر قبضہ کر لیں۔ یہ تمام انسانوں کے نزدیک جنگ کا اصول اور قانون ہے کہ دشمن کے سامانِ رسد کو تباہ کر دیا جائے یا اس پر قبضہ کر لیا جائے۔\nنبی کریم صلی اللہ علیہ وسلم نے قریش کے قافلے کو روکنے اور اس پر قبضہ کرنے کا جو عزم کیا تھا، اس میں تعجب کی کوئی بات نہیں تھی کیونکہ یہ ایک معلوم بات تھی کہ اس تجارتی قافلے میں وہ اموال بھی شامل ہیں جو مکہ سے مدینہ کی طرف ہجرت کرنے والے مسلمانوں کی ملکیت تھے اور مشرکین نے ظلم و زیادتی سے ان پر قبضہ جما لیا تھا۔ ایسے دشمن کے اموال چھیننے اور ان کے مقابلے میں ہتھیار اٹھانے کی کارروائی کو ڈکیتی اور لوٹ مار سے تعبیر نہیں کیا جا سکتا۔(1)\n§بدری صحابہ رضی اللہ عنہم کی تعداد\nغزوہ بدر میں شرکت کرنے والوں کی تعداد کے متعلق مصادرِ صحیحہ میں اختلاف پایا جاتا ہے۔ امام بخاری رحمہ اللہ نے تین سو دس سے کچھ زائد افراد کا تذکرہ کیا ہے۔ امام مسلم رحمہ اللہ نے تین سو انیس افراد بتائے ہیں۔ یعنی آپ کے ساتھ بدر کی طرف جانے والوں کی تعداد تین سو تیرہ سے تین سو انیس تک تھی۔ ان میں 82 سے 86 تک مہاجرین تھے، 61 اوسی اور 170 خزرجی تھے۔ براء بن عازب رضی اللہ عنہ کہتے ہیں کہ مجھے اور ابن عمر رضی اللہ عنہما کو بدر کے دن چھوٹا ہونے کی بنا پر لشکر میں شامل نہیں کیا گیا۔(2) اس دن مہاجرین کی تعداد ساٹھ (60) سے زیادہ تھی اور انصار دو سو چالیس (240) سے زیادہ افراد تھے۔ حافظ ابن حجر رحمہ اللہ نے شرکائے بدر کی تعداد پر مفصل تبصرہ کیا ہے۔ وہ لکھتے ہیں کہ زہیر، اسرائیل اور سفیان رحمہم اللہ کی روایات میں تین سو دس (310) اور کچھ زائد افراد تھے۔ دس سے اوپر افراد کی تعداد معلوم نہیں۔ صحیح مسلم میں ان کی تعداد تین سو انیس (319) بیان کی گئی ہے۔ مسند البزار میں تین سو سترہ (317) ہے۔ امام احمد، بزار اور طبرانی نے اہل بدر کو تین سو تیرہ (313) شمار کیا ہے۔ جمہور کے نزدیک ان کی تعداد تین سو تیرہ (313) ہی ہے۔ ابن اسحاق نے تین سو چودہ (314) کا قول بھی نقل کیا ہے۔ ایک دوسری حسن سند سے طبرانی اور بیہقی میں سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم بدر کی طرف نکلے۔ آپ صلی اللہ علیہ وسلم نے لشکر میں شامل افراد کی گنتی کا حکم دیا تو ان کی تعداد تین سو چودہ (314) تھی۔ آپ نے پھر گنتی کرنے کا حکم دیا۔ ابھی صحابہ کرام رضی اللہ عنہم یہ شمار کر ہی","",{"v":500375,"fn":"(1) موسوعة الغزوات الكبرىٰ لباشميل: 78/1\n(2) صحيح البخاري: 3956,3957، صحيح مسلم: 1763"}],[2446,"رہے تھے کہ ایک آدمی اپنے کمزور اونٹ پر سوار آ گیا تو اب ان کی تعداد تین سو پندرہ (315) ہو گئی۔\nیہ روایت سابقہ روایت کے منافی نہیں کیونکہ ممکن ہے کہ پہلی مرتبہ انھوں نے نبی صلی اللہ علیہ وسلم کو اور دوسری مرتبہ آنے والے صحابی کو شمار نہ کیا ہو اور تین سو انیس والی روایت میں اس بات کا احتمال ہے کہ ان میں وہ لوگ بھی شامل کیے گئے ہوں جو ابھی نو عمر تھے اور وہ بھی لشکر کے ساتھ نکلے تھے لیکن انھیں قتال کی اجازت نہ ملی جن میں براء بن عازب، ابن عمر اور انس رضی اللہ عنہم شامل ہیں۔\nایک روایت میں ہے کہ قتال میں شرکت کرنے والوں کی تعداد تین سو پانچ یا چھ تھی جیسا کہ ابن جریر رحمہ اللہ نے ابن عباس رضی اللہ عنہما کی روایت بیان کی ہے کہ بلاشبہ اہل بدر تین سو چھ افراد تھے۔ ابن سعد رحمہ اللہ نے تین سو پانچ کا ذکر کیا ہے۔ گویا انھوں نے رسول کریم صلی اللہ علیہ وسلم کو گنتی میں شامل نہیں کیا۔ ان اقوال میں اس طرح مطابقت دی جا سکتی ہے کہ بقیہ آٹھ افراد اہل بدر ہی میں شمار کیے جاتے ہیں، ہر چند وہ معرکے میں شامل نہیں تھے لیکن اللہ کے رسول صلی اللہ علیہ وسلم نے انھیں مال غنیمت سے حصہ دیا تھا کیونکہ وہ آپ صلی اللہ علیہ وسلم کے حکم سے بعض اہم ضرورتوں کی بنا پر معرکے میں شریک نہیں ہو سکے، مثلاً: رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی رقیہ رضی اللہ عنہا بیمار تھیں تو آپ صلی اللہ علیہ وسلم نے سیدنا عثمان رضی اللہ عنہ کو سیدہ رقیہ رضی اللہ عنہا کی تیمارداری کے لیے ان کے پاس رہنے کا حکم دیا۔ طلحہ اور سعید بن زید رضی اللہ عنہما کو نبی صلی اللہ علیہ وسلم نے قریش کے قافلے کی جاسوسی کے لیے بھیجا تھا۔ ابولبابہ رضی اللہ عنہ کو مقام روحاء سے مدینہ منورہ میں اپنا جانشین بنا کر واپس بھیج دیا۔ عاصم بن عدی رضی اللہ عنہ کو قباء اور عوالی میں اپنا جانشین بنایا۔ حارث بن حاطب رضی اللہ عنہ کو بنو عمرو بن عوف پر جانشین بنایا۔ حارث بن صمہ رضی اللہ عنہ گر گئے اور ان کی ہڈی ٹوٹ گئی، چنانچہ آپ نے انھیں بھی مقام روحاء سے مدینہ واپس بھیج دیا اور خوات بن جبیر رضی اللہ عنہ کے ساتھ بھی یہی معاملہ پیش آیا۔\n[تصویر: مدرسۃ الروحاء]","",{"v":500376,"im":["v5_p376.jpg"]}],[2447,"ابن سعد رحمہ اللہ نے انھی لوگوں کا تذکرہ کیا ہے۔ ابن سعد کے علاوہ دوسرے سیرت نگاروں اور مؤرخین نے سہل رضی اللہ عنہ کے والد سعد بن مالک ساعدی کا ذکر کیا ہے کہ وہ راستے ہی میں وفات پا گئے تھے۔ سعد بن عبادہ رضی اللہ عنہ کے بارے میں اختلاف ہے کہ آیا وہ بدر میں حاضر ہوئے تھے یا کسی کام کی غرض سے انھیں بھی واپس کر دیا گیا تھا۔ احیحہ کے آزاد کردہ غلام صبیح کو بیماری کی وجہ سے واپس بھیج دیا گیا۔ یہ بھی کہا گیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جعفر بن ابو طالب رضی اللہ عنہ کو غنیمت کا حصہ دیا تھا۔(1)\nسعد بن عبادہ رضی اللہ عنہ کے بارے میں واقدی نے لکھا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سعد رضی اللہ عنہ کے لیے غنیمت سے حصہ بھی نکالا اور انھیں اجر کی نوید بھی سنائی۔ آپ نے فرمایا: اگرچہ سعد بن عبادہ لڑائی میں حاضر نہیں ہوئے لیکن وہ اس میں شرکت کی رغبت ضرور رکھتے تھے۔ یہ اس لیے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے جہاد کا آغاز کیا تو یہ انصار کے محلوں میں جا کر انھیں جہاد کی ترغیب دیتے تھے۔ اسی دوران میں انھیں چوٹ آ گئی جس کی وجہ سے وہ غزوہ بدر میں شریک نہ ہو سکے۔ اسی بنا پر رسول اللہ صلی اللہ علیہ وسلم نے انھیں غنیمت سے حصہ بھی دیا اور انھیں اجر کی نوید بھی سنائی۔\nرسول اللہ صلی اللہ علیہ وسلم نے سعد بن مالک ساعدی رضی اللہ عنہ کے لیے بھی حصہ نکالا اور انھیں اجر کی نوید سنائی کیونکہ انھوں نے آپ کے ساتھ جانے کی تیاری کی، پھر بیمار ہو گئے اور وفات پا گئے۔ اسی طرح انصار کے دو آدمیوں کے لیے بھی حصہ نکالا، البتہ ان چار صحابہ کے بارے میں سیرت نگاروں اور مؤرخین کا ویسا اتفاق نہیں جس طرح کہ پہلے آٹھ لوگوں کے بارے میں اتفاق ہے کہ وہ بدر میں حاضر نہیں ہوئے تھے لیکن اللہ کے رسول صلی اللہ علیہ وسلم نے انھیں مال غنیمت سے حصہ بھی دیا اور انھیں اجر کی نوید بھی سنائی۔(2)\n§مسلمانوں کی مدینہ سے روانگی\nابن سعد رحمہ اللہ نے ذکر کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم ہفتہ 12 رمضان المبارک 2ھ کو اپنے ساتھیوں کے ساتھ مدینہ منورہ سے بدر کی طرف نکلے۔ ابن ہشام نے روانگی کی تاریخ آٹھ رمضان المبارک ذکر کی ہے۔ جب آپ بنو دینار کے درے تک پہنچ گئے تو آپ نے بیوت السقیا میں پڑاؤ ڈالا۔ یہ مدینہ کے بالکل قریب جگہ ہے۔ وہاں پہنچ کر آپ نے صحابہ کرام کا جائزہ لیا۔ تمام لوگوں کو آپ کے سامنے پیش کیا گیا۔ عبداللہ بن عمر، اسامہ بن زید، رافع بن خدیج، براء بن عازب، اسید بن ظہیر، زید بن ارقم اور زید بن ثابت رضی اللہ عنہم کو چھوٹا ہونے کی بنا پر واپس بھیج دیا گیا۔ نبی صلی اللہ علیہ وسلم کو بخوبی ادراک تھا کہ ابوسفیان اور قافلے کے دیگر محافظ اپنے قافلے کو بچانے کی ہر ممکن کوشش","",{"v":500377,"fn":"(1) فتح الباري: 364,365/7\n(2) المغازي للواقدي: 103,104/1"}],[2448,"[تصویر: مسجد بیوت السقیا]\nکریں گے اور وہ لڑائی سے بھی دریغ نہیں کریں گے۔ اسی لیے آپ صلی اللہ علیہ وسلم نے کم عمر صحابہ رضی اللہ عنہم کو لڑائی میں شریک ہونے کی اجازت نہ دی۔ سعد بن ابی وقاص رضی اللہ عنہ بیان کرتے ہیں کہ میں نے اپنے بھائی عمیر بن ابی وقاص کو دیکھا کہ وہ چھپ رہے ہیں۔ میں نے پوچھا: بھائی! کیا بات ہے؟ تو انھوں نے کہا: مجھے ڈر ہے مبادا اللہ کے رسول صلی اللہ علیہ وسلم مجھے دیکھ لیں اور چھوٹا سمجھ کر واپس بھیج دیں جبکہ میں لشکر کے ساتھ نکلنا چاہتا ہوں، ممکن ہے اللہ تعالیٰ مجھے شہادت سے سرفراز فرما دے۔ سعد رضی اللہ عنہ فرماتے ہیں: جب عمیر کو رسول اللہ صلی اللہ علیہ وسلم کے سامنے پیش کیا گیا تو آپ نے انھیں صغر سنی کی بنا پر کہا: ’’تم لوٹ جاؤ۔‘‘ عمیر یہ سن کر رو پڑے تو اللہ کے رسول صلی اللہ علیہ وسلم نے انھیں اجازت مرحمت فرما دی، پھر وہ معرکہ بدر میں 16 برس کی عمر میں جام شہادت نوش کر گئے۔(1)\nرسول اللہ صلی اللہ علیہ وسلم نے بیوت سقیا کے کنویں سے پانی پیا اور صحابہ کرام رضی اللہ عنہم کو بھی حکم دیا کہ اس کنویں کا پانی پیئیں، پھر وہاں نماز ادا کی۔ اس دن آپ صلی اللہ علیہ وسلم نے اہل مدینہ کے لیے یہ دعا کی:\n«اللَّهُمَّ إِنَّ إِبْرَاهِيمَ عَبْدُكَ وَخَلِيلُكَ وَنَبِيُّكَ، دَعَاكَ لِأَهْلِ مَكَّةَ، وَإِنِّي مُحَمَّدٌ عَبْدُكَ وَنَبِيُّكَ، أَدْعُوكَ لِأَهْلِ الْمَدِينَةِ أَنْ تُبَارِكَ لَهُمْ فِي صَاعِهِمْ وَمُدِّهِمْ وَثِمَارِهِمْ، اللَّهُمَّ حَبِّبْ إِلَيْنَا الْمَدِينَةَ، وَاجْعَلْ مَا بِهَا مِنَ الْوَبَاءِ بِخُمَّ، اللَّهُمَّ إِنِّي قَدْ حَرَّمْتُ مَا بَيْنَ لَابَتَيْهَا كَمَا حَرَّمَ إِبْرَاهِيمُ خَلِيلُكَ مَكَّةَ»\n’’اے اللہ! ابراہیم علیہ السلام تیرے بندے، تیرے خلیل اور تیرے نبی تھے۔ انھوں نے اہل مکہ کے لیے تجھ سے دعا","",{"v":500378,"fn":"(1) المغازي للواقدي: 35/1، الطبقات لابن سعد: 12/2، السيرة لابن هشام: 612/2","im":["v5_p378.jpg"]}],[2449,"[تصویر: غدیر خم]\nمانگی تھی۔ میں محمد تیرا بندہ اور تیرا نبی ہوں۔ میں اہل مدینہ کے لیے تجھ سے دعا مانگتا ہوں کہ تو ان کے لیے ان کے صاع میں، ان کے مد میں اور ان کے پھلوں میں برکت نازل فرما۔ اے اللہ! مدینہ کو ہمارے لیے محبوب بنا دے اور وہاں جو وبائی امراض ہیں، انھیں خم میں بھیج دے۔ اے اللہ! میں نے مدینہ کے دو کناروں کے درمیانی علاقے کو حرم بنا دیا ہے جس طرح تیرے خلیل ابراہیم علیہ السلام نے مکہ کو حرم بنا دیا تھا۔‘‘(1)\n§مدنی لشکر کا ساز و سامان\nرسول اللہ صلی اللہ علیہ وسلم مدینہ سے نکلے تو لشکر نے غزوے کے لیے کوئی خاص اہتمام نہ کیا، چنانچہ پورے لشکر میں صرف دو گھوڑے تھے: ایک زبیر بن عوام رضی اللہ عنہ کا اور دوسرا مقداد بن اسود کندی رضی اللہ عنہ کا تھا۔ اور ستر اونٹ تھے جن پر تمام لوگ دو دو، تین تین اور چار چار کر کے باری باری سوار ہوتے تھے۔ ایک اونٹ پر رسول اکرم صلی اللہ علیہ وسلم اور سیدنا ابولبابہ اور سیدنا علی رضی اللہ عنہم سواری میں شریک تھے۔ جب نبی کریم صلی اللہ علیہ وسلم کے پیدل چلنے کی باری آتی تو وہ دونوں عرض کرتے: ’’آپ سوار رہیں، ہم آپ کی طرف سے بھی پیدل چلیں گے۔‘‘ آپ صلی اللہ علیہ وسلم اپنے مشفقانہ انداز میں فرماتے:\n«مَا أَنْتُمَا بِأَقْوَىٰ مِنِّي وَلَا أَنَا بِأَغْنَىٰ عَنِ الْأَجْرِ مِنْكُمَا»\n’’نہ تم مجھ سے زیادہ طاقتور ہو اور نہ میں ثواب سے بے نیاز ہوں۔‘‘(2)\n§مدینہ میں نیابت\nمدینے کا انتظام شروع میں عبداللہ ابن ام مکتوم رضی اللہ عنہ کے سپرد تھا، پھر جب آپ صلی اللہ علیہ وسلم مقام روحاء تک پہنچے تو آپ نے ابولبابہ رضی اللہ عنہ کو مدینے کا ناظم بنا کر واپس روانہ کر دیا اور ان کی جگہ سیدنا مرثد بن ابی مرثد رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کے ساتھ سواری میں شریک ہو گئے۔(3)","",{"v":500379,"fn":"(1) جامع الترمذي: 3914، مسند أحمد: 309/5، صحيح ابن حبان: 61,62/9، حديث: 3746\n(2) مسند أحمد: 411/1، المغازي للواقدي: 38/1\n(3) \"خم\" کلاب بن مرہ کا کنواں تھا جو مکہ اور مدینہ کے درمیان جحفہ کے قریب واقع تھا۔ * السيرة لابن هشام: 612/2","im":["v5_p379.jpg"]}],[2450,"اسلامی لشکر کی گزرگاہیں\n[تصویر: وادی عقیق]\nمحمد رسول اللہ صلی اللہ علیہ وسلم کی غایت لڑائی لڑنا نہیں تھی۔ بلکہ آپ صلی اللہ علیہ وسلم تو محض قریش مکہ کے قافلے کی تلاش و جستجو میں نکلے تھے۔ بہت محدود تعداد میں فدایانِ حق آپ صلی اللہ علیہ وسلم کے ساتھ تھے۔ آپ صلی اللہ علیہ وسلم انھی کی معیت میں مدینہ منورہ سے نکلے اور درے سے گزرتے ہوئے اگلی منزل کی طرف روانہ ہو گئے۔ اس سفر کی منازل میں یکے بعد دیگرے عقیق، اولات الجیش، تربان، ملل، غمیس الحمام، صخیرات الیمام، السیالہ، فج الروحاء کے معروف مقامات آئے۔ آپ صلی اللہ علیہ وسلم دمبدم ان علاقوں کے نشیب و فراز سے گزرتے ہوئے شنوکے کے مقام پر پہنچے۔ یہ ایک درمیانی راستہ ہے۔\n[تصویر: وادی ملل]\nرسول اللہ صلی اللہ علیہ وسلم جب بئر الروحاء تک پہنچے تو یہاں آپ صلی اللہ علیہ وسلم نے نئی حکمت عملی اختیار فرمائی۔ یہاں آپ نے آگے بڑھتے ہوئے مکے کا راستہ بائیں جانب چھوڑ دیا اور دائیں جانب چلتے ہوئے النازیہ کی طرف مڑ گئے۔ جب آپ عرق الظبیہ پہنچے تو اچانک آپ کی ایک بدو سے ملاقات ہو گئی۔\nصحابہ کرام رضی اللہ عنہم نے اس بدو کو گھیر لیا اور اس سے قریش مکہ کے تجارتی قافلے کے بارے میں پوچھا کہ کیا تم نے\n[تصویر: وادی السیالہ]\n[تصویر: غمیس الحمام]","",{"v":500380,"im":["v5_p380.jpg"]}],[2451,"وہ قافلہ دیکھا ہے؟ اس بدو نے لاعلمی کا اظہار کیا۔ پھر وہ بدو صحابہ کرام رضی اللہ عنہم سے پوچھنے لگا: کیا تم میں اللہ کے رسول صلی اللہ علیہ وسلم ہیں؟ صحابہ کرام رضی اللہ عنہم نے جواب دیا: ہاں! یہ اللہ کے رسول صلی اللہ علیہ وسلم ہیں۔ ان کی خدمت میں سلام کرو۔ چنانچہ اس بدو نے آگے بڑھ کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں سلام پیش کیا، پھر عرض کرنے لگا: مجھے قافلے کے بارے میں تو قطعی کوئی علم نہیں ہے۔ ہاں! البتہ اگر آپ اللہ کے رسول ہیں تو یہ فرمائیے میری اس اونٹنی کے پیٹ میں کیا ہے؟\n[تصویر: بئر روحاء]\n[تصویر: صخیرات الیمام]\nسیدنا سلمہ بن سلامہ بن وقش رضی اللہ عنہ فرمانے لگے: ارے! یہ بات اللہ کے رسول صلی اللہ علیہ وسلم سے مت پوچھو، ادھر آؤ میں تمھیں بتاتا ہوں کہ اس کے پیٹ میں کیا ہے۔ تم نے اس اونٹنی سے بدمعاشی کی ہے اور اس کے پیٹ میں تمھارا بچہ کلبلا رہا ہے۔ رسول اللہ صلی اللہ علیہ وسلم کے مزاج مبارک پر یہ گفتگو نہایت گراں گزری۔ آپ صلی اللہ علیہ وسلم نے سیدنا سلمہ رضی اللہ عنہ سے فرمایا: ’’بس کرو، تم نے اسے رسوا کر دیا ہے۔‘‘ پھر اللہ کے رسول صلی اللہ علیہ وسلم نے سلمہ رضی اللہ عنہ سے ناراضی کا اظہار فرماتے ہوئے منہ پھیر لیا۔(1)\n[تصویر: عرق الظبیہ]","",{"v":500381,"fn":"(1) السيرة لابن هشام: 613/2","im":["v5_p381.jpg"]}],[2452,"[تصویر: نقشہ: اسلامی لشکر کی پیش قدمی (مدینہ تا بدر)]\nاہم مقامات: مدینہ منورہ، ذوالحلیفہ (آبار علی)، وادی عقیق، ذات الجیش، تربان، الغریض، ملل، وادی ملل، غمیس الحمام، صخیرات الیمام، السیالہ، الفقارہ، الفریش، المضیبعہ، رحقان، وادی رحقان، الروحاء، شنوکے، النازیہ، عرق الظبیہ، الصفراء (الواسطہ)، وادی الصفراء، وادی ذفران، الحمراء، بدر، بحیرہ احمر (بحیرہ قلزم)\nاشارات: طریق رسول صلی اللہ علیہ وسلم (مدینہ تا بدر)، جدید شاہراہ، ندی (وادی)\nمدینہ سے فاصلے: ذوالحلیفہ 10 کلومیٹر، ذات الجیش 13 کلومیٹر، وادی تربان 29 کلومیٹر، وادی ملل 41 کلومیٹر، السیالہ 47 کلومیٹر، عرق الظبیہ 70 کلومیٹر، الروحاء (مسجد) 75 کلومیٹر، سطوان 77 کلومیٹر، مصرف (مسجد) 80 کلومیٹر، النازیہ (چشمہ) 84 کلومیٹر، وادی رحقان 90 کلومیٹر، بئر الشیخ 114 کلومیٹر، الصفراء (الواسطہ) 135 کلومیٹر، وادی ذفران 140 کلومیٹر، الواسطہ (الصفراء) 142 کلومیٹر، الحمراء (الکبریٰ) 145 کلومیٹر، کثیب الحنان 152 کلومیٹر، بدر 155 کلومیٹر\nحواشی نقشہ: تربان وادی ملل کی ایک معاون وادی (ندی) ہے جو 24 کلومیٹر دور مضرحات علی سے نکلتی ہے اور پھر جنوب مغرب سے ہو کر وادی ملل میں جا گرتی ہے۔ شنوکے ایک ندی ہے جو شمال سے الروحاء کی طرف آتی ہے۔ الروحاء میں ابو الروحاء نامی کنواں ہے جسے بیج بھی کہتے ہیں۔ وادی الصفراء کا وہ حصہ جو بدر سے گزرتا ہے وادی جلیل یا وادی بدر کہلاتا ہے، آگے چل کر یہ وادی الصلوة کہلاتی ہے۔ پہاڑی ٹیلہ کثیب الحنان بدر کے شمال میں واقع ہے، اس لیے بدر کو نقشوں میں بدر حنین بھی لکھا جاتا ہے۔","",{"v":500382,"im":["v5_p382.jpg"]}],[2453,"§مشرک سے استعانت\nام المؤمنین سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم بدر کی جانب روانہ ہوئے۔ ابھی آپ حرہ وبرہ ہی پہنچے تھے کہ ایک آدمی آیا جس کی بہادری اور جرأت کے تذکرے زبان زدِ عام تھے۔ صحابہ کرام رضی اللہ عنہم نے اسے دیکھا تو بہت خوش ہوئے۔ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچا تو عرض گزار ہوا: اے اللہ کے رسول صلی اللہ علیہ وسلم! میں بھی آپ کے ساتھ شریک ہونا چاہتا ہوں تاکہ کچھ مال حاصل کر سکوں۔ آپ صلی اللہ علیہ وسلم نے اس سے سوال کیا: ’’کیا تو اللہ اور اس کے رسول پر ایمان رکھتا ہے؟‘‘\nاس نے انکار میں جواب دیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:\n«فَارْجِعْ فَلَنْ أَسْتَعِينَ بِمُشْرِكٍ»\n’’تو لوٹ جا، میں کسی مشرک سے ہرگز مدد نہیں لیتا۔‘‘\nسیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں: نبی اکرم صلی اللہ علیہ وسلم آگے بڑھ گئے۔ جب الشجرہ کے پاس پہنچے تو وہی شخص دوبارہ آپ کے پاس آیا اور اپنی بات دہرائی۔ جواب میں نبی صلی اللہ علیہ وسلم نے پھر وہی سوال دہرایا۔ تیسری دفعہ وہ ’’البیداء‘‘ نامی جگہ آپ کے سامنے آیا تو آپ صلی اللہ علیہ وسلم نے اس سے پھر وہی دریافت فرمایا: ’’کیا تو اللہ اور اس کے رسول صلی اللہ علیہ وسلم پر ایمان رکھتا ہے؟‘‘ اس نے عرض کی: ’’جی ہاں!‘‘ اس پر آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اب تو ہمارے ساتھ شریک ہو سکتا ہے۔‘‘(1)\n[تصویر: حرہ وبرہ]","",{"v":500383,"fn":"(1) صحيح مسلم: 1817، سنن أبي داود: 2732","im":["v5_p383.jpg"]}],[2454,"§مدنی لشکر وادی صفراء میں\nرسول اللہ صلی اللہ علیہ وسلم مکہ مکرمہ کی طرف جانے والی شاہراہِ عام کو چھوڑ کر النازیہ پہنچے، پھر النازیہ کے ایک گوشے سے گزر کر وادی رحقان پار کی، اس کے بعد درہ الصفراء (الواسطہ) سے گزرے، پھر درے سے اتر کر وادی الصفراء (الواسطہ) کی طرف چلے۔ وہاں سے قبیلہ جہینہ کے دو آدمیوں بسبس بن عمرو اور عدی بن ابو زغباء رضی اللہ عنہما کو تجارتی قافلے کے حالات کا پتہ لگانے کے لیے بدر روانہ فرمایا۔ یہ دونوں صحابی رسول اللہ صلی اللہ علیہ وسلم کے حکم کی بجا آوری کے لیے روانہ ہو گئے۔\nجب وہ بدر کے پاس پہنچے تو انھوں نے پانی کے قریب ایک ٹیلے کے پاس اپنے اونٹ بٹھائے اور اپنا مشکیزہ لے کر پانی کے پاس آئے۔ ادھر مجدی بن عمرو جہنی موجود تھا۔ وہاں ان دونوں نے دو لڑکیوں کی گفتگو سنی۔ ان میں سے ایک نے دوسری لڑکی کو اس طرح پکڑا ہوا تھا جیسے کوئی قرض خواہ اپنے قرض کا مطالبہ کر رہا ہو۔ جس لڑکی کو پکڑا ہوا تھا، اس نے اپنی سہیلی سے کہا: کل یا پرسوں قافلہ آئے گا، میں ان کا پانی بھروں گی۔ اس کے عوض مجھے جو اجرت ملے گی، اس سے میں تیرا قرض ادا کر دوں گی۔ مجدی نے کہا: تو نے بالکل ٹھیک بات کی، پھر ان دونوں کے درمیان جھگڑا چکا دیا۔ عدی اور بسبس رضی اللہ عنہما یہ بات سن کر اپنے اونٹوں پر بیٹھے اور اللہ کے رسول صلی اللہ علیہ وسلم کی خدمت میں پہنچ کر سارا ماجرا بیان کر دیا۔\nرسول اللہ صلی اللہ علیہ وسلم وادی صفراء کے پاس پہنچے۔ یہ وادی دو پہاڑوں کے درمیان واقع تھی۔ آپ نے ان دونوں پہاڑوں کے متعلق دریافت فرمایا تو بتایا گیا کہ ایک کا نام مُسْلِح (ہتھیار بند سپاہیوں کی چوکی) اور دوسرے کا نام\n[تصویر: وادی الصفراء کا ایک منظر]","",{"v":500384,"im":["v5_p384.jpg"]}],[2455,"مُخْرِی (جائے پاخانہ) ہے، پھر آپ صلی اللہ علیہ وسلم نے ان کے باشندوں کے متعلق دریافت کیا تو آپ کو بتایا گیا کہ اس پر بنو غفار کے دو قبیلے بنو النار (آگ والے) اور بنو حُرَاق (جلانے والے) آباد ہیں۔ آپ صلی اللہ علیہ وسلم نے یہ باتیں ناپسند فرمائیں اور وہاں سے گزرنے کا ارادہ ترک کر دیا، پھر اس علاقے کو بائیں جانب چھوڑتے ہوئے وادی ذفران سے گزرنے لگے۔(1)\n§ابوسفیان کی ہوشیاری\nقریشی قافلے کا سالار ابوسفیان حد درجہ بیدار مغز اور محتاط تھا۔ اسے اچھی طرح معلوم تھا کہ مکے کا راستہ خطرات سے گھرا ہوا ہے، اس لیے جونہی اس کے قدم شمال سے حجاز کے علاقے کی طرف پڑے، اس کے جاسوس آگے آگے یہ خبر معلوم کرنے کے لیے پھیل گئے کہ محمد صلی اللہ علیہ وسلم کی طرف سے قافلے پر حملہ کرنے کی کیا تیاری کی جا رہی ہے؟ اسے زیادہ دقت کا سامنا نہ کرنا پڑا۔ اسے جلد ہی معلوم ہو گیا کہ محمد صلی اللہ علیہ وسلم مدینہ سے اپنے صحابہ کو لے کر نکلے ہیں۔ اس موقع پر ابوسفیان کے سامنے خوفناک خطرات منڈلانے لگے۔ اس نے اسی وقت فیصلہ کیا کہ مکہ میں سردارانِ قریش کو اس نازک صورت حال سے فوری آگاہ کرنا چاہیے اور ان سے مدد طلب کرنی چاہیے۔\n§مکے میں خطرے کا اعلان\nجب ابوسفیان کو معلوم ہو گیا کہ محمدی لشکر اس کی تاک میں ہے تو اس نے فوراً ضمضم بن عمرو غفاری کو اجرت دے کر مکے بھیجا اور تاکید کی کہ وہاں جا کر قافلے کی حفاظت کے لیے آواز لگائے، پھر ابوسفیان نے احتیاطاً قافلے کا\n[تصویر: وادی ذفران]","",{"v":500385,"fn":"(1) السيرة لابن هشام: 614/2","im":["v5_p385.jpg"]}],[2456,"رخ ساحل کی طرف پھیر دیا۔\n§عاتکہ بنت عبدالمطلب کا خواب\nضمضم بن عمرو غفاری کے مکہ پہنچنے سے تین رات پہلے سردار عبدالمطلب کی صاحبزادی عاتکہ نے ایک خواب دیکھا جس کا اس پر بڑا گہرا اثر پڑا۔ اس نے اپنے بھائی عباس بن عبدالمطلب رضی اللہ عنہ کو بلا بھیجا۔ وہ آئے تو عاتکہ نے کہا: بھائی جان! اللہ کی قسم! آج رات میں نے ایک خواب دیکھا ہے جس نے مجھے بہت خوفزدہ کر دیا ہے۔ مجھے اندیشہ ہے کہ آپ کی قوم پر کوئی آفت نازل ہونے والی ہے۔ میں آپ کو جو بات بتانے والی ہوں، اسے افشا نہ کرنا۔ انھوں نے کہا: بتلاؤ تو سہی کیا بات ہے؟ انھوں نے خواب بیان کرنا شروع کیا، کہتی ہیں: میں کیا دیکھتی ہوں کہ ایک شتر سوار آیا اور وادی ابطح میں کھڑا ہو گیا، پھر نہایت بلند آواز سے چیخ کر کہنے لگا:\n«أَلَا انْفِرُوا يَا لَغُدْرِ لِمَصَارِعِكُمْ فِي ثَلَاثٍ»\n’’خبردار، اے دھوکے بازو! تین دن کے اندر اندر اپنی قتل گاہوں کی طرف نکلو۔‘‘\nمیں نے دیکھا کہ لوگ اس شتر سوار کے گرد جمع ہو گئے، پھر وہ مسجد میں داخل ہوا۔ لوگ اس کے پیچھے پیچھے تھے اور اس کا اونٹ کعبہ کی چھت پر کھڑا تھا۔ اس شخص نے وہ صدا پھر بلند کی، پھر میں نے اس اونٹ کو جبل ابی قبیس پر کھڑا دیکھا، وہاں جا کر اس شتر سوار نے پھر وہی نعرہ لگایا اور ایک بھاری بھرکم چٹان کو نیچے لڑھکا دیا۔ وہ چٹان ریزہ ریزہ ہو گئی اور اس کی کنکریاں قریش کے تمام گھروں میں آ گریں۔\n[تصویر: جبل ابی قبیس کا منظر]\nخواب سن کر سیدنا عباس رضی اللہ عنہ بولے: اللہ کی قسم! یہ تو بہت اہم خواب ہے۔ تو اسے چھپائے رکھنا، کسی سے اس کا تذکرہ نہ کرنا۔\n§عاتکہ کا خواب قریش کی مجالس میں\nسیدنا عباس رضی اللہ عنہ عاتکہ کو خواب مخفی رکھنے کی نصیحت کر کے وہاں سے نکلے تو انھیں راستے میں ولید بن عقبہ بن","",{"v":500386,"im":["v5_p386.jpg"]}],[2457,"ربیعہ مل گیا۔ یہ ان کا دوست تھا۔ سیدنا عباس نے خواب کا ذکر اس سے کر دیا اور اسے تاکید کرتے ہوئے کہا کہ یہ بات آگے کسی سے نہ کرنا۔ ولید نے یہ بات اپنے باپ عقبہ کو بتا دی۔ اس طرح یہ راز افشا ہو گیا۔ سیدنا عباس رضی اللہ عنہ شام کو حرم میں طواف کے لیے گئے۔ وہاں ابوجہل کو دیکھا کہ قریش کی ایک مجلس میں بیٹھا ہے اور وہاں اس خواب کا تذکرہ ہو رہا ہے۔\n§ابوجہل اور سیدنا عباس رضی اللہ عنہ میں تکرار\nسیدنا عباس رضی اللہ عنہ کہتے ہیں کہ ابوجہل نے مجھے دیکھا اور کہا: ابوالفضل! طواف سے فارغ ہو کر میرے پاس آنا، چنانچہ میں طواف سے فارغ ہو کر اس کے پاس چلا گیا۔ ابوجہل نے مجھے مخاطب کرتے ہوئے کہا: اے بنو عبدالمطلب! تم میں یہ نبیہ کب پیدا ہوئی ہے؟ میں نے اس سے کہا: تمھارا کیا مطلب ہے؟ اس نے کہا: میں اس خواب کا ذکر کر رہا ہوں جو عاتکہ نے دیکھا ہے۔ میں نے انجان بنتے ہوئے کہا: اس نے کیا دیکھا ہے؟ ابوجہل نے کہا: اے بنو عبدالمطلب! کیا تم اس پر مطمئن نہیں کہ تم میں سے ایک نبی کا ظہور ہوا ہے اور اب تمھاری عورتوں نے بھی نبوت کا دعویٰ شروع کر دیا ہے، پھر اس نے کہا: عاتکہ کا کہنا ہے کہ ایک شتر سوار نے تین دن میں نکلنے کا کہا ہے۔ ہم تین دن انتظار کریں گے۔ اگر ان تین دنوں میں اس کا خواب سچا نہ ہوا تو ہم یہ لکھ کر ہر جگہ چسپاں کر دیں گے: «إِنَّكُمْ أَكْذَبُ أَهْلِ بَيْتٍ فِي الْعَرَبِ» ’’بلاشبہ ملک عرب میں تمھارا گھرانہ سب سے زیادہ جھوٹا ہے۔‘‘ سیدنا عباس رضی اللہ عنہ کہتے ہیں: مجھے مجبوراً اس خواب کا انکار کرنا پڑا۔ اس کے بعد ہم جدا ہو گئے۔ ایک روایت میں ہے، سیدنا عباس رضی اللہ عنہ نے ابوجہل کو کہا: ’’او سرین پر خوشبو لگانے والے! تو باز نہیں آتا؟‘‘\n§خواتین بنی عبدالمطلب کی عباس رضی اللہ عنہ سے تکرار\nسیدنا عباس رضی اللہ عنہ کہتے ہیں کہ شام کو جب میں گھر آیا تو بنو عبدالمطلب کی کوئی خاتون ایسی نہ تھی جس نے میری درگت نہ بنائی ہو اور یہ نہ کہا ہو: پہلے وہ خبیث فاسق تمھارے مردوں پر زبان درازی کرتا رہا تو تم نے اسے برداشت کر لیا، اب وہ تمھارے خاندان کی خواتین پر آوازیں کس رہا ہے اور تم خاموشی سے سن رہے ہو۔ تم میں اتنی غیرت بھی نہیں کہ تم اس کا منہ توڑ جواب دے سکو۔ کہتے ہیں کہ میں نے یہ کہہ کر جان چھڑائی کہ اچھا! بس کرو، اب جیسے ہی وہ مجھے ملے گا، میں اس کا کام تمام کر دوں گا۔\n§عباس رضی اللہ عنہ ابوجہل کی تلاش میں\nسیدنا عباس رضی اللہ عنہ فرماتے ہیں کہ عاتکہ کے خواب دیکھنے کے تین دن بعد میں صبح سویرے نکلا۔ میں غصے سے","",{"v":500387}],[2458,"لال پیلا ہوا جا رہا تھا۔ مجھے یوں لگ رہا تھا جیسے مجھ سے کوئی بہت بڑی چیز چھن گئی ہو جسے میں حاصل کرنا چاہتا تھا۔ میں مسجد میں داخل ہوا اور دیکھا کہ ابوجہل وہاں موجود ہے۔ میں نے آج دل میں ٹھان لی تھی کہ میں اس کے پاس جاؤں گا اور اگر اس نے دوبارہ کوئی ایسی بات کی تو میں اس کا تیا پانچا کر دوں گا۔ ابوجہل دبلا پتلا، تیکھے نقوش والا، چرب زبان اور عقابی نگاہ رکھنے والا آدمی تھا۔ میں اس کی طرف بڑھا تو وہ تیزی سے بھاگتا ہوا مسجد کے دروازے کی طرف چل دیا۔ میں نے دل میں کہا کہ یہ میرے ڈر کی وجہ سے بھاگا ہے کہ میں اسے برا بھلا کہوں گا، حالانکہ یہ بات نہ تھی۔ اس نے ضمضم بن عمرو کی آواز سن لی تھی جو میں نہ سن سکا۔ وہ وادی کے درمیان اونٹ پر کھڑا چیخ رہا تھا۔ اس نے عرب کے دستور کے مطابق اپنے اونٹ کی ناک چیر دی، کجاوہ الٹا کیا، کرتا پھاڑا اور چیخ کر بولا: اے قریش کی جماعت! اپنے قافلے کو بچاؤ جس میں خوشبو، کپڑے اور تمھارے دیگر اموال ابوسفیان کی نگرانی میں موجود ہیں۔ محمد (صلی اللہ علیہ وسلم) نے اپنے ساتھیوں کے ساتھ اس قافلے پر چڑھائی کر دی ہے۔ مجھے یقین نہیں کہ تم اسے پا سکو۔\nمدد…… مدد……!\nاس انتہائی غیر متوقع حادثے نے ہمیں دفعتاً اس قدر ہلا کر رکھ دیا کہ پھر ہم اپنی جگہ سنبھلنے ہی نہیں پائے اور ہمیں ایک دوسرے سے کوئی بات کرنے کا کوئی موقع نہیں مل سکا۔\n§جنگ کے لیے اہل مکہ کی تیاری\nقافلہ تجارت کو پیش آنے والے ممکنہ حادثے کی خبر قریش پر انتہائی گراں گزری۔ تمام سردارانِ قریش طیش میں آ گئے کیونکہ یہ معاملہ ان کی رسوائی کا باعث اور ان کے اقتصادی مفادات کو چیلنج کرنے کے ساتھ ساتھ دیگر قبائل کی نظر میں ان کے مقام و مرتبہ کو گرا دینے کے مترادف تھا، اس لیے وہ اپنی پوری جنگی طاقت کے ساتھ اس سنگین چیلنج کا مقابلہ کرنے کے لیے نکل کھڑے ہوئے۔ انھوں نے کہا: محمد (صلی اللہ علیہ وسلم) اور ان کے ساتھی سمجھتے ہیں کہ یہ قافلہ بھی ابن حضرمی کے قافلے جیسا ہے؟ نہیں! ہرگز نہیں، اللہ کی قسم! انھیں پتہ چل جائے گا کہ ہمارا معاملہ کچھ اور ہے۔ مکہ میں جوش و خروش کا عجیب عالم تھا۔ ان میں سے ہر شخص اس جنگ میں شریک ہونے کا خواہاں تھا۔ اگر کسی مجبوری کے تحت کوئی آدمی خود نہیں جا سکا تو اس نے اپنی جگہ کسی دوسرے کو بھیجا۔ جو مال دار تھے، وہ ناداروں کی مالی اعانت کر رہے تھے، انھیں اسلحہ اور سواری مہیا کر رہے تھے۔ اس طرح گویا سبھی نکل پڑے، خصوصاً معززین میں سے کوئی پیچھے نہ رہا، سوائے ابولہب کے۔ اس نے اپنی جگہ عاصی بن ہشام بن مغیرہ کو بھیجا۔ عاصی بن ہشام نے ابولہب سے چار ہزار درہم بطور قرض لیے تھے۔","",{"v":500388}],[2459,"ابولہب نے اُس سے کہا: اگر تم میری جگہ اس لشکر میں شرکت کرو تو میں تمھیں یہ قرض معاف کر دوں گا، چنانچہ عاصی بن ہشام ابولہب کی جگہ اس لشکر میں شریک ہوا۔(1)\nادھر سہیل بن عمرو جو قریش کا خطیب اور سردار تھا، وہ اپنے خطبے سے عام لوگوں کے جذبات برانگیختہ کر رہا تھا۔ وہ کہہ رہا تھا:\n’’کیا تم محمد (صلی اللہ علیہ وسلم) اور یثرب کے بے دینوں کو اس بات کی اجازت دے دو گے کہ وہ تمھارے مال لوٹ کر لے جائیں؟ جس شخص کو دولت کی ضرورت ہو، اس کے لیے میری تجوریاں کھلی ہیں، جس شخص کو اسلحے کی ضرورت ہو، وہ میرے اسلحہ خانے سے اسلحہ لے سکتا ہے۔‘‘\nقریش نے بنو عدی کے سوا گرد و پیش کے قبائل کو بھی لشکر میں شامل کیا۔ بنو عدی سے کوئی شخص جنگ میں شریک نہیں ہوا۔\n§امیہ رسول اللہ صلی اللہ علیہ وسلم کا ارشاد سن کر لرز گیا\nسیدنا سعد بن معاذ رضی اللہ عنہ بیان کرتے ہیں کہ وہ زمانہ جاہلیت میں امیہ بن خلف کے دوست تھے۔ امیہ جب بھی مدینہ سے گزرتا تو وہ سعد رضی اللہ عنہ کے پاس قیام کرتا تھا۔ اسی طرح سعد رضی اللہ عنہ جب مکہ سے گزرتے تو امیہ کے ہاں ٹھہرتے تھے۔ جب نبی صلی اللہ علیہ وسلم ہجرت کر کے مدینہ منورہ تشریف لائے تو ایک مرتبہ سعد رضی اللہ عنہ عمرہ کرنے مکہ تشریف لائے اور امیہ کے پاس قیام کیا۔ انھوں نے امیہ سے کہا: میرے لیے کوئی تنہائی کا وقت دیکھو تا کہ میں بیت اللہ کا طواف کروں۔\nامیہ انھیں دوپہر کے وقت ساتھ لے کر نکلا۔ ان سے ابو جہل کی ملاقات ہو گئی۔ اس نے امیہ سے پوچھا: ابو صفوان! یہ تمھارے ساتھ کون ہیں؟ امیہ نے بتایا کہ یہ سعد بن معاذ ہیں۔ ابو جہل سعد رضی اللہ عنہ سے کہنے لگا: میں تمھیں مکہ میں امن کے ساتھ طواف کرتا ہوا نہ دیکھوں کیونکہ تم لوگوں نے بے دینوں کو پناہ دے رکھی ہے اور اس خیال میں ہو کہ تم ان کی مدد کرو گے۔ اللہ کی قسم! اگر اس وقت تم ابو صفوان کے ساتھ نہ ہوتے تو اپنے گھر صحیح سلامت واپس نہیں جا سکتے تھے۔ اس پر سیدنا سعد رضی اللہ عنہ نے گرج کر کہا: اللہ کی قسم! اگر آج تم نے مجھے طواف سے روکا تو میں بھی مدینے کی طرف سے تمھارا راستہ بند کر دوں گا اور یہ تمھارے لیے زبردست مشکلات کا سبب بن جائے گا۔ امیہ کہنے لگا: سعد! ابو الحکم (ابو جہل) کے سامنے بلند آواز سے نہ بولو، یہ اس وادی کا سردار ہے۔ سعد رضی اللہ عنہ نے کہا:","",{"v":500389,"fn":"(1) السيرة لابن هشام: 607/2-610"}],[2460,"امیہ! ایسی بات نہ کرو، اللہ کی قسم! میں اللہ کے رسول صلی اللہ علیہ وسلم سے سن چکا ہوں کہ تو ان (صحابہ) کے ہاتھوں مارا جائے گا۔ امیہ نے پوچھا: کیا وہ مکہ میں مجھے قتل کریں گے؟ انھوں نے جواب دیا: اس کا مجھے علم نہیں۔ امیہ یہ سن کر گھبرا گیا اور جب اپنے گھر لوٹا تو اپنی بیوی سے کہا: ام صفوان! کیا تم نے نہیں سنا کہ سعد میرے متعلق کیا کہہ رہے ہیں؟ اس نے پوچھا: کیا کہہ رہے ہیں؟ امیہ نے کہا: وہ بتا رہے ہیں کہ محمد (صلی اللہ علیہ وسلم) نے انھیں خبر دی ہے کہ وہ کسی دن مجھے قتل کر دیں گے۔ میں نے پوچھا: کیا وہ مکہ میں مجھے قتل کریں گے تو انھوں نے کہا: اس کی مجھے خبر نہیں۔ امیہ کہنے لگا: اللہ کی قسم! اب میں مکہ سے باہر کبھی نہیں جاؤں گا۔\n§امیہ بن خلف کا انکار اور ابو جہل کا اصرار\nبدر کی لڑائی کے لیے جب ابو جہل نے قریش کو تیاری کے لیے کہا اور آواز لگائی کہ اپنے قافلے کی مدد کے لیے نکلو تو امیہ نے لڑائی میں شرکت پسند نہیں کی۔ ابو جہل اس کے پاس آیا اور کہنے لگا: ابو صفوان! تم وادی کے سردار ہو۔ جب لوگ دیکھیں گے کہ تم ہی لڑائی میں نہیں نکلتے تو دوسرے لوگ بھی نہیں نکلیں گے۔ ابو جہل مسلسل اصرار کرتا رہا۔ بالآخر مجبور ہو کر امیہ نے کہا: اگر تم مجھے مجبور کرتے ہو تو اللہ کی قسم! میں ایسا تیز رفتار اونٹ خریدوں گا جس کا ثانی مکہ میں کوئی اونٹ نہ ہو، پھر امیہ نے اپنی بیوی سے کہا: ام صفوان! میرا سامان تیار کر دے۔ اس نے کہا: ابو صفوان! کیا تم اپنے یثربی بھائی کی بات بھول گئے؟ امیہ بولا: میں بھولا نہیں، بس میں ان کے ساتھ تھوڑی دور تک ہی جاؤں گا۔ جب امیہ نکلا تو راستے میں جس منزل پر ٹھہرنا ہوتا، یہ اپنے اونٹ کا گھٹنا باندھ دیتا۔ وہ مسلسل ایسے ہی کرتا رہا یہاں تک کہ اللہ تعالیٰ نے اسے بدر میں قتل کرا دیا۔(1)\nایک روایت میں ہے: امیہ سعد رضی اللہ عنہ سے مسلسل یہی کہتا رہا: ابو الحکم کے سامنے اپنی آواز بلند نہ کرو اور انھیں روکتا رہا۔ آخر سعد رضی اللہ عنہ کو غصہ آ گیا اور انھوں نے امیہ سے کہا: چل پرے ہٹ، میں نے محمد صلی اللہ علیہ وسلم سے سنا ہے کہ وہ تمھیں قتل کریں گے۔ اس نے پوچھا: مجھے؟ تو سعد رضی اللہ عنہ نے بتایا: ہاں۔ امیہ کہنے لگا: اللہ کی قسم! محمد صلی اللہ علیہ وسلم جب کوئی بات کر دیتے ہیں تو وہ جھوٹ نہیں ہوتی۔ پھر وہ اپنی بیوی کے پاس آیا، کہنے لگا: کیا تجھے پتہ ہے، میرے یثربی بھائی نے مجھ سے کیا کہا ہے؟ اس نے پوچھا: کیا کہا ہے؟ امیہ نے بتایا کہ محمد (صلی اللہ علیہ وسلم) مجھے قتل کریں گے۔ اس کی بیوی نے کہا: اللہ کی قسم! محمد (صلی اللہ علیہ وسلم) جھوٹ نہیں بولتے۔ پھر ایسا ہوا کہ اہل مکہ بدر کی لڑائی کے لیے نکلنے لگے اور امیہ کو بھی بلانے والا آیا تو امیہ سے اس کی بیوی نے کہا: تمھیں یاد نہیں تمھارا یثربی بھائی تمھیں کیا خبر دے گیا تھا۔","",{"v":500390,"fn":"(1) صحيح البخاري: 3950"}],[2461,"راوی بیان کرتے ہیں کہ اس یاد دہانی پر امیہ نے شرکت جنگ کا ارادہ ترک کرنا چاہا لیکن ابو جہل نے کہا: تم وادی مکہ کے رئیس ہو، اس لیے کم از کم ایک یا دو دن ہمارے ساتھ چلو۔ وہ چلا گیا اور اللہ تعالیٰ نے اسے بدر ہی میں ہلاک کر دیا۔(1)\n§عقبہ کی حماقت کام کر گئی\nابو جہل نے ایک چالاکی یہ دکھائی کہ جنگ پر اکسانے کے لیے عقبہ بن ابی معیط کو امیہ بن خلف کے پیچھے لگا دیا۔ عقبہ احمق آدمی تھا۔ اس نے انگیٹھی میں انگارے ڈالے اور اس میں عود ڈال کر امیہ کے پاس دھونی دیتا ہوا آیا اور امیہ کے سامنے انگیٹھی رکھ کر بولا: محترمہ! آپ دھونی لیں، آپ مرد نہیں عورت ہیں۔ امیہ نے کہا: تجھے اور جو تو لایا ہے، اللہ اسے برباد کرے، پھر وہ اٹھا، سفر کی تیاری کی اور لشکر کے ساتھ روانہ ہو گیا۔(2)\nمکی لشکر اگرچہ بظاہر طاقت، عزم اور پختگی سے لبریز نظر آتا تھا لیکن ان کے دلوں میں خوف اور بزدلی بیٹھی ہوئی تھی۔ وہ اندر سے بری طرح تذبذب کا شکار تھے اور اس طرح سہمے ہوئے جا رہے تھے جیسے موت کے منہ میں دھکیلے جا رہے ہوں۔(3)\nعتبہ اور شیبہ کے بارے میں آپ رسول اللہ صلی اللہ علیہ وسلم کے سفر طائف میں پڑھ آئے ہیں کہ ان دونوں نے بدر میں جانے کے لیے اپنی زرہیں نکالیں۔ ان کے غلام عداس (رضی اللہ عنہ) نے ان کی طرف دیکھا کہ وہ اپنی زرہیں اور آلات جنگ درست کر رہے ہیں تو عداس نے پوچھا: کدھر کا ارادہ ہے؟ انھوں نے کہا: کیا تمھیں وہ آدمی یاد ہے جس کی طرف ہم نے اپنے باغ سے انگور بھیجے تھے؟ اس نے کہا: ہاں! وہ مجھے یاد ہیں۔ کہنے لگے: بس ہم اسی سے لڑنے جا رہے ہیں۔ یہ سن کر عداس رو پڑے۔ کہنے لگے: آپ مت جائیں، اللہ کی قسم! وہ نبی ہیں۔ عداس کا رونا دھونا کسی کام نہ آیا۔ انھوں نے عداس کی بات نہیں مانی۔ وہ بڑے طمطراق سے نکلے یہاں تک کہ بدر میں قتل ہو گئے۔\n§کفار کا پانسا موافق نہ نکلا\nقریش کے افراد فال نکالنے کے لیے اپنے بڑے بت ہبل کے پاس گئے۔ امیہ بن خلف، عتبہ اور شیبہ نے تیر نکالا تو وہ تیر نکلا جس میں جنگ میں شرکت کی ممانعت لکھی ہوئی تھی۔ وہ ڈھیلے پڑ گئے لیکن ابو جہل انھیں مجبور کر کے ساتھ لے گیا اور کہنے لگا: آج پانسے نہ پھینکو، ہم اپنے قافلے سے پیچھے نہیں رہیں گے۔ جب زمعہ بن اسود ذی طویٰ","",{"v":500391,"fn":"(1) صحيح البخاري: 3632\n(2) السيرة لابن هشام: 607/2-617، البداية والنهاية: 255/3-258، دلائل النبوة للبيهقي: 100/3-106\n(3) الاكتفاء: 13/2-15، المغازي للواقدي: 34/1-50، مرويات غزوة بدر لأحمد باوزير، ص: 138"}],[2462,"پہنچا اور اس نے فال نکالی تو عدم شرکت کا تیر نکلا۔ وہ غصے سے لال پیلا ہو گیا۔ اس نے پھر تیر نکالا تو دوبارہ ممانعت کا تیر نکلا۔ اس نے غضب ناک ہوتے ہوئے تیر ہی توڑ دیا اور کہا: میں نے آج کے دن کی طرح کبھی اتنا جھوٹا تیر نہیں دیکھا۔ اتنے میں سہیل بن عمرو پاس سے گزرا۔ اس نے پوچھا: ابو الحکیمہ! کیا بات ہے، بڑے غصے میں نظر آ رہے ہو؟ زمعہ نے ساری بات کہہ ڈالی۔ اس نے کہا: چھوڑو یار! یہ تیر تو خواہ مخواہ جھوٹی فال نکالتے ہیں۔ مجھے عمیر بن وہب نے بھی ایسی ہی بات بتائی ہے جو تم نے بتائی ہے، پھر وہ یہی بات کرتے کرتے آگے بڑھ گئے۔(1)\n§مکی لشکر کو قبائل بنو بکر سے خطرہ\nجب قریش نے تیاری مکمل کر لی اور جنگ کے لیے روانہ ہونے لگے تو انھیں اچانک اس خیال نے چونکا دیا مبادا بنو کنانہ کی شاخ بنو بکر کے لوگ ہمارے پیچھے سے حملہ کر دیں۔ اس کی وجہ یہ تھی کہ قریش نے ایک موقع پر بنو بکر کے ایک شخص کو قتل کر دیا تھا۔ بعد ازاں بنو معیص بن عامر بن لؤی کا ایک شخص حفص بن آخیف کا بیٹا اپنی کوئی گم شدہ چیز تلاش کرتا ہوا ضجنان نامی جگہ سے گزر رہا تھا۔ یہ بہت خوبرو اور نوجوان تھا۔ وہاں بنو بکر کا سردار عامر بن یزید بن عامر بن ملوح بھی موجود تھا۔ اس نے اس لڑکے کو دیکھا تو اسے بہت بھلا محسوس ہوا۔ اس نے پوچھا: اے لڑکے! تم کون ہو؟ اس نے بتایا کہ میں حفص بن آخیف قرشی کا بیٹا ہوں۔ یہ سنتے ہی اس کی آتش انتقام بھڑک اٹھی۔ لڑکا جب واپس مڑا تو اس نے اپنے قبیلے سے کہا: کیا تمھیں قریش میں کسی کا خون کرنے کی رغبت ہے؟ سب نے کہا: کیوں نہیں! بے شک ان کے ذمے ہمارا خون ہے۔ اس نے کہا: جو شخص اس قریشی لڑکے کو قتل کر دے گا، وہ گویا اپنے خون کا انتقام لے لے گا، چنانچہ بنو بکر کے ایک آدمی نے اس لڑکے کا پیچھا کیا اور اسے موت کے گھاٹ اتار دیا۔ قریش نے بنو بکر کے سردار عامر سے شکایت کی تو اس نے کہا: اے قریش کی جماعت! بلاشبہ تمھارے ذمے ہمارا ایک خون تھا، لہذا ہم نے بھی تمھارا ایک آدمی قتل کر کے حساب چکا دیا، اب تم کیا چاہتے ہو؟ اگر تم دیت لینا چاہتے ہو تو پہلے ہمارے آدمی کی دیت دو، پھر ہم تمھیں دیت ادا کر دیں گے۔ اگر قصاص چاہتے ہو تو ہم نے آدمی کے بدلے آدمی قتل کر دیا ہے۔ بس اب تمھارا اور ہمارا حساب برابر ہو گیا۔ قریش نے کہا: ٹھیک ہے۔ پھر قریش نے خون کا مطالبہ ترک کر دیا۔\nکچھ عرصے کے بعد بنو بکر کا سردار عامر مر الظہران سے گزر رہا تھا۔ مقتول کے بھائی مکرز بن حفص نے اسے دیکھا تو یکا یک اس پر عقاب کی طرح جھپٹ پڑا اور اسے قتل کر دیا۔ بعد ازاں اس کا پیٹ اسی کی تلوار سے چاک کر","",{"v":500392,"fn":"(1) المغازي للواقدي: 48/1"}],[2463,"[تصویر: وادی فاطمہ (مر الظہران)]\nڈالا، پھر اس نے رات کی تاریکی میں عامر کی تلوار خانہ کعبہ کے غلاف کے ساتھ لٹکا دی۔ صبح کے وقت جب قریش بیت اللہ آئے اور انھوں نے تلوار دیکھی تو بولے: یہ تو بنو بکر کے سردار عامر کی تلوار ہے۔ اسے مکرز نے قتل کر دیا ہے۔ یہ قتل بنو بکر اور قریش میں دشمنی کا سبب بن گیا۔ سالہا سال ان کی دشمنی اسی طرح چلتی رہی حتی کہ دعوت اسلام کی گونج بلند ہوئی تو ان کی دشمنی وقتی طور پر دب گئی۔ اب جب مشرکین اسلام اور مسلمانوں کو نیست و نابود کرنے کا منصوبہ بنا کر بدر کی جانب نکلنے لگے تو انھیں بنو بکر کی طرف سے انتقام کا خوف لاحق ہو گیا۔\n§ابلیس لعین، سراقہ بن مالک کی شکل میں\nقریب تھا کہ قریش اس خیال سے ارادہ جنگ سے باز آ جاتے لیکن عین اسی وقت ابلیس لعین بنو کنانہ کے سردار سراقہ بن مالک مدلجی (رضی اللہ عنہ) کے روپ میں ظاہر ہوا اور بولا: میں بھی تمھارا رفیق کار ہوں۔ میں تمھیں ضمانت دیتا ہوں کہ بنو کنانہ تمھارے پیچھے کوئی ناگوار کام نہیں کریں گے۔(1)\n§مکی لشکر روانگی کے وقت\nجب بنو بکر (بنو کنانہ) کی طرف سے انھیں پروانہ امن مل گیا تو یہ لوگ اپنے گھروں سے گھمنڈ اور تکبر کی حالت میں نکلے جیسا کہ فرمان باری تعالیٰ ہے:\n﴿خَرَجُوا مِنْ دِيَارِهِمْ بَطَرًا وَرِئَاءَ النَّاسِ وَيَصُدُّونَ عَنْ سَبِيلِ اللَّهِ وَاللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ﴾ ۱","",{"v":500393,"fn":"(1) السيرة لابن هشام: 612/2","im":["v5_p393.jpg"]}],[2464,"وہ اپنے گھروں سے اتراتے ہوئے اور لوگوں کو (اپنی شان) دکھاتے ہوئے نکلے اور وہ (لوگوں کو) اللہ کی راہ سے روکتے تھے۔ اور جو کچھ وہ کر رہے ہیں، اللہ اس کا احاطہ کیے ہوئے ہے۔(1)\nامام قرطبی رحمہ اللہ فرماتے ہیں: ابو جہل اور اس کے دیگر رفقاء بدر کے دن اپنے تجارتی قافلے کی مدد کے لیے نکلے اور اپنے ساتھ گانے بجانے کا سامان اور گانے والیاں بھی لے کر آئے۔ جب وہ جحفہ پہنچے تو خُناف کنانی نے، جو ابو جہل کا دوست تھا، اپنے بیٹے کے ہاتھ ابو جہل کی طرف تحائف بھیجے اور کہلا بھیجا کہ اگر تم پسند کرو تو میں تمھاری مدد کے لیے کچھ آدمی بھیج دوں یا خود تمھاری مدد کے لیے اپنی قوم کے ساتھ آ جاؤں؟ ابو جہل نے جواب دیا: اللہ کی قسم! اگر ہم محمد (صلی اللہ علیہ وسلم) کے گمان کے مطابق اللہ سے جنگ کر رہے ہیں تو اس ذات کا مقابلہ کرنے کی ہم میں طاقت نہیں اور اگر ہم لوگوں سے لڑنے جا رہے ہیں تو اللہ کی قسم! ہم میں ان سے لڑنے کی قوت موجود ہے۔(2)\nلشکر کفار کی مدینہ کی طرف جارحانہ روانگی کی کیفیت کے بارے میں رسول اللہ صلی اللہ علیہ وسلم کا ارشاد یہ ہے: ’’وہ (مشرکین مکہ) اپنی دھار اور ہتھیار لے کر اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے خار کھاتے ہوئے، جوش انتقام سے چور اور غیظ و غضب سے مغلوب ہو کر نکلے۔ وہ اس بات پر کچکچا رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے صحابہ نے اہل مکہ کے قافلے پر آنکھ اٹھانے کی جرات کیسے کی؟‘‘(3) ایسے ہی جذبات کے زیر اثر یہ لوگ نہایت تیز رفتاری سے شمال کے رخ پر بدر کی جانب چلے جا رہے تھے۔\n§مشرکین کا لشکر اور اسلحہ\nابتدا میں مشرکین کی تعداد ایک ہزار تین سو تھی۔ ایک روایت کے مطابق ان کے پاس دو سو گھوڑے، چھ سو زرہیں اور بڑی کثرت سے اونٹ تھے۔ ان کے ساتھ گلوکارائیں بھی تھیں جو دف بجا بجا کر مسلمانوں کی ہجو کر رہی تھیں اور مشرکین کو گیت گا گا کر جوش دلاتی اور مسلمانوں کے خلاف ان کی آتش غضب کو بھڑکاتی تھیں۔ جب یہ نکلے تو ان کی ہر ایک ادا سے غرور ٹپک رہا تھا۔ اسی کو قرآن مجید نے یوں بیان کیا ہے:\n﴿وَلَا تَكُونُوا كَالَّذِينَ خَرَجُوا مِنْ دِيَارِهِمْ بَطَرًا وَرِئَاءَ النَّاسِ وَيَصُدُّونَ عَنْ سَبِيلِ اللَّهِ وَاللَّهُ بِمَا يَعْمَلُونَ مُحِيطٌ﴾\n’’اور ان لوگوں کی طرح مت ہو جاؤ جو اپنے گھروں سے اتراتے اور لوگوں کو (اپنی شان) دکھلاتے ہوئے نکلے اور وہ اللہ کی راہ سے (لوگوں کو) روکتے تھے، اور وہ جو کچھ کر رہے ہیں اللہ اس کا احاطہ کیے ہوئے ہے۔‘‘(4)","",{"v":500394,"fn":"(1) الأنفال 8:47\n(2) تفسير القرطبي، الأنفال 8:47\n(3) الرحيق المختوم، ص: 226\n(4) الأنفال 8:47"}]])